'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('spontaneity','Spontaneity is formed from spontaneous + -ity; spontaneous comes from Latin spontaneus, “of one’s free will,” from sponte, “of one’s own accord.”',C('spontaneity.s1','行为','The director liked the actors’ spontaneity, so she left room for unscripted reactions.','导演喜欢演员自然流露的表现，因此留出了即兴发挥的空间。','the spontaneity of a response; act with spontaneity','名词，指未经事先安排、自然发生的行为或表现。','unscripted reactions are not planned.','行为'),M('The spontaneity of the scene came from following every line in a fixed script without variation.','The scene’s spontaneity came from the actors reacting naturally without a fixed script.','完全照固定剧本表演不属于即兴自然的表现。','meaning'),[Q(1,'Spontaneity in acting means…','natural, unplanned behavior','strictly following every rehearsed movement','performing without any audience','The noun names unplanned and unconstrained action.','meaning'),Q(1,'Why did the director leave room for unscripted reactions?','She valued the actors’ natural responses.','She wanted every word dictated in advance.','She was testing a spool of film.','The context links spontaneity to improvisation.','context'),Q(1,'Which phrase is natural?','the spontaneity of the performance','the spontaneous of the performance','spontaneity performance ofly','Of links the quality to the performance.','grammar'),Q(1,'Spontaneity is formed from spontaneous plus…','-ity','-less','-er','The suffix forms an abstract noun for a quality.','word-formation')]);
P('spontaneous','Spontaneous comes from Latin spontaneus, “of one’s own accord”; it describes something happening without an outside order or something done naturally without rehearsal.',[C('spontaneous.s1','行为','A spontaneous cheer rose from the crowd when the home team scored.','主队进球时，人群中自发响起一阵欢呼。','a spontaneous reaction/decision; spontaneous applause','形容词，指没有外界命令或事先安排而发生的。','crowd reacts without direction.','行为'),C('spontaneous.s2','表演','Her spontaneous delivery made the rehearsed scene sound like a real conversation.','她自然随性的表达让排练过的场景听起来像真实交谈。','a spontaneous manner; sound/look spontaneous','形容词，也指表达自然、不像事先排练。','delivery does not sound rehearsed.','表演')],M('The spontaneous cheer was ordered in advance by the director and repeated from a written cue.','The spontaneous cheer began without anyone directing or scheduling it.','事先命令和安排与spontaneous的核心义相反。','meaning'),[Q(1,'A spontaneous cheer happens…','without an outside order or plan','only after a written command','at a fixed time every day','Sense 1 means happening by itself.','meaning'),Q(2,'A spontaneous delivery sounds…','natural rather than rehearsed','mechanical and read word for word','like a quiet liquid','Sense 2 concerns an unrehearsed manner.','context'),Q(1,'Which phrase is correct?','a spontaneous reaction to the goal','a spontaneousness reaction','spontaneously reaction to goal','Spontaneous is an adjective modifying reaction.','grammar'),Q(1,'Spontaneous traces to Latin spontaneus, meaning…','of one’s own free will','from a spool of wire','in a public spotlight','The Latin source emphasizes acting on one’s own accord.','word-formation')]);
P('spontaneously','Spontaneously is spontaneous + -ly; it means by one’s own free will or as a natural, unplanned result of a feeling.',[C('spontaneously.s1','行为','Several residents spontaneously offered to help clear the fallen branches.','几位居民自发提出帮忙清理倒下的树枝。','act/respond spontaneously; spontaneously offer','副词，表示自愿且未经安排地采取行动。','residents volunteer without a call.','行为'),C('spontaneously.s2','情绪','She spontaneously hugged her sister when she heard the good news.','听到好消息后，她情不自禁地拥抱了姐姐。','laugh/cry/hug spontaneously','副词，也表示感情自然流露、未经思索地发生。','emotion prompts immediate gesture.','情绪')],M('The residents spontaneously volunteered after the organizer assigned each person a task by name.','The residents spontaneously volunteered before anyone assigned them a task.','先被逐一指派任务不是自发提出帮忙。','meaning'),[Q(1,'Residents who spontaneously offered help…','volunteered without being asked or assigned','were ordered to help individually','refused all assistance','The adverb means freely and without planning.','meaning'),Q(2,'She hugged her sister spontaneously because…','the gesture came naturally from her feelings','she followed a rehearsed stage direction','she had been given a written order','This use describes an unplanned emotional response.','context'),Q(1,'Which sentence uses the adverb correctly?','The crowd spontaneously began to cheer.','The crowd was spontaneous began cheer.','The crowd began a spontaneously cheer.','Spontaneously modifies the verb phrase began to cheer.','grammar'),Q(1,'Spontaneously is formed by adding -ly to…','spontaneous','spool','sport','The adverb comes from the adjective spontaneous.','word-formation')]);
P('spool','Spool comes from Middle Dutch spoele; it is a small cylinder around which thread, wire, film, or similar material is wound, and the verb means wind material onto one.',[C('spool.s1','工具','The electrician placed the loose copper wire on a spool to keep it from tangling.','电工把松散的铜线绕在线轴上，免得它缠结。','a spool of thread/wire; wind onto a spool','名词，指绕存线、金属丝或胶片等的圆柱形轴。','wire is wound around a cylinder.','工具'),C('spool.s2','操作','The camera operator spooled the film carefully onto the take-up reel.','摄影师小心地把胶片绕到收片轴上。','spool wire/film onto; spool out','及物动词，指把细长材料绕在线轴上或从轴上放出。','film is wound onto reel.','操作')],M('The electrician put the wire on a spool by leaving it in a loose pile on the floor.','The electrician wound the wire around a spool to keep it orderly.','线轴用于绕存材料，松散堆放并没有绕在线轴上。','meaning'),[Q(1,'A spool is…','a small cylinder used to wind thread, wire, or film','a flat surface for cutting vegetables','a device that measures sound','That is the object’s source sense.','meaning'),Q(2,'To spool film onto a reel is to…','wind it around the reel','cut it into unrelated pieces','project it onto a wall','The verb means wind material onto a spool.','context'),Q(1,'Which phrase is natural?','a spool of copper wire','a spoolful copper wires','spool for wire into a of','Of introduces the material wound on the spool.','grammar'),Q(1,'Spool came into English from Middle Dutch…','spoele','sponte','sport','The noun is borrowed from Middle Dutch spoele.','word-formation')]);
P('spoon','Spoon comes from Old English spōn, originally a chip or splinter; it is a shallow-bowled utensil, and the verb means move or serve food with one.',[C('spoon.s1','餐具','She stirred the honey into her tea with a small spoon.','她用一把小勺把蜂蜜搅进茶里。','a teaspoon/tablespoon; a spoon for soup','名词，指带浅碗和手柄、用来进食或盛取食物的餐具。','utensil stirs liquid.','餐具'),C('spoon.s2','烹饪','Spoon the sauce over the vegetables just before serving.','上菜前把酱汁舀到蔬菜上。','spoon food into/onto; spoon out','动词，指用勺把食物舀起、移动或盛出。','sauce is moved using a spoon.','烹饪')],M('She stirred the tea with a spoon by using a fork with sharp tines instead.','She stirred the tea with a spoon, a utensil with a shallow bowl and handle.','带尖齿的是叉子，不是勺子。','distinction'),[Q(1,'A spoon is a utensil with…','a shallow bowl and a handle','a sharp blade and no handle','a long reel for winding film','That matches the noun sense.','meaning'),Q(2,'To spoon sauce over vegetables is to…','move it with a spoon onto them','bake it inside the vegetables','wind it around a cylinder','Spoon as a verb means serve or move food using a spoon.','context'),Q(1,'Which instruction is natural?','Spoon the soup into the bowls.','Fork the soup into the bowls with a spoon.','Spoon at soup into bowlly.','The verb takes the food and destination as objects.','grammar'),Q(1,'Spoon originally referred to a…','chip or splinter','small song','serious ceremony','The Old English ancestor meant a chip or splinter.','word-formation')]);
P('spoonful','Spoonful combines spoon + -ful and means as much as a spoon can hold.',C('spoonful.s1','烹饪','Add one spoonful of sugar, taste the tea, and then decide whether it needs more.','加一匙糖，尝尝茶，再决定是否还要加。','a spoonful of sugar/medicine; two spoonfuls','名词，指一勺所能盛下的量。','amount fits in one spoon.','烹饪'),M('She added a spoonful of sugar, pouring an entire twenty-kilogram sack into the cup.','She added one spoonful of sugar, an amount that fits in a spoon.','一整袋糖远超一匙所能盛下的量。','measurement'),[Q(1,'A spoonful of sugar is…','as much sugar as a spoon holds','a whole sack of sugar','a type of cutlery handle','The suffixal measure refers to a spoon’s capacity.','meaning'),Q(1,'Why taste the tea after one spoonful?','To judge whether that measured amount is enough','To see if the spoon can wind film','To check a sports score','The example uses spoonful as a serving measure.','context'),Q(1,'Which plural is standard?','two spoonfuls of medicine','two spoonsful of medicine','two spoonful medicine','Spoonful normally takes plural -s at the end.','plural'),Q(1,'The suffix -ful in spoonful signals…','the amount a spoon holds','a person who uses a spoon','the absence of a spoon','It forms a measure based on capacity.','word-formation')]);
P('sporadic','Sporadic comes from Greek sporadikos, “scattered,” through Latin; it describes events occurring irregularly or things spread thinly over an area.',[C('sporadic.s1','频率','Sporadic power cuts continued during the storm, but the electricity was on most of the time.','风暴期间偶尔发生停电，但大多数时候供电正常。','sporadic incidents/outbreaks; sporadic and irregular','形容词，指偶尔发生、没有固定规律。','outages occur now and then.','频率'),C('sporadic.s2','分布','The survey found sporadic trees across the dry plain rather than a continuous forest.','调查发现干旱平原上零散分布着树木，而不是连成一片的森林。','sporadic growth/settlement; sporadically distributed','形容词，也指在空间或时间上稀疏分散。','trees are separated across area.','分布')],M('Sporadic outages happened at exactly the same minute every day without interruption.','Sporadic outages happened irregularly at scattered times during the storm.','固定每日同一时刻发生不属于sporadic。','meaning'),[Q(1,'Sporadic power cuts are…','occasional and irregular','continuous at every moment','scheduled at the same time daily','Sense 1 concerns irregular timing.','meaning'),Q(2,'Sporadic trees across a plain are…','scattered rather than forming a continuous forest','planted in one dense grove','missing from the entire region','Sense 2 concerns sparse distribution.','context'),Q(1,'Which phrase is natural?','sporadic reports of delays','sporadically reports of delays','reports sporadicly of delays','Sporadic is an adjective modifying reports.','grammar'),Q(1,'The Greek source sporadikos meant…','scattered','fully joined','very loud','The word’s origin conveys scattered distribution.','word-formation')]);
P('sporadically','Sporadically is formed from sporadic + -ally; it means at irregular intervals or in scattered locations.',C('sporadically.s1','频率','The old clock worked sporadically, stopping for an hour and then ticking again.','这只旧钟时走时停，停一个小时后又会重新滴答。','occur/work sporadically; appear sporadically','副词，表示偶尔发生、断断续续且没有规律。','clock starts and stops irregularly.','频率'),M('The clock worked sporadically, ticking perfectly every second without stopping.','The clock worked sporadically, sometimes stopping and sometimes starting again.','每秒稳定运转是规律连续的，不是断断续续。','meaning'),[Q(1,'A clock that works sporadically…','works at irregular intervals','runs perfectly without interruption','is wound onto a spool','The adverb means now and then, irregularly.','meaning'),Q(1,'What does the old clock do?','It stops and starts unpredictably.','It ticks every second without pause.','It sings a sonnet.','The example illustrates irregular operation.','context'),Q(1,'Which sentence is natural?','The signal appeared sporadically in the hills.','The signal sporadic appearedly in hills.','The signal was sporadicly appearance.','Sporadically modifies the verb appeared.','grammar'),Q(1,'Sporadically is formed from the adjective…','sporadic','spore','spoonful','The adverb is based on sporadic.','word-formation')]);
P('spore','Spore comes from Greek spora, “seed, sowing,” through Latin; it is a minute reproductive cell or body that can develop without joining another cell.',C('spore.s1','生物','A fern spore landed in damp soil and later developed into a new plant.','一枚蕨类孢子落在潮湿土壤中，后来发育成一株新植物。','fungal/fern spore; release/spread spores','名词，指能独立发育的微小繁殖体。','spore develops without fusion.','生物'),M('The fern reproduced by a spore that had to fuse with a second spore before it could develop.','The fern reproduced by a spore that could develop without fusion with another cell.','此义项中的孢子无需与另一细胞融合便可发育。','meaning'),[Q(1,'A spore is…','a minute reproductive body able to develop without fusion','a large animal egg that must be fertilized','a sound wave used underwater','That is the source definition.','meaning'),Q(1,'What happened to the fern spore?','It developed in damp soil into a new plant.','It dissolved into a liquid.','It became a songbird.','The example shows reproductive development.','context'),Q(1,'Which phrase is natural?','fungal spores spread through the air','fungal sporeful spreadly air','spores to spread the fungal of','Spores can be released and spread.','grammar'),Q(1,'The Greek source spora meant…','seed or sowing','spoon or ladle','stage or platform','The biological term comes from a Greek word for seed/sowing.','word-formation')]);
P('sport','Sport came through Old French desport, “pleasure, pastime,” ultimately from Latin portare; it means an athletic activity, enjoyment or a friendly person, and as a verb means wear or display proudly.',[C('sport.s1','运动','Rowing is a demanding sport that requires strength and careful timing.','赛艇是一项需要力量和精准配合的高强度运动。','play/take up a sport; a team sport','名词，指需要体力和技巧的运动或比赛项目。','activity uses physical effort and skill.','运动'),C('sport.s2','交往','Be a sport and help us carry these boxes before the rain starts.','帮个忙吧，趁下雨前和我们一起搬这些箱子。','be a good sport; a bit of sport','名词，可指乐趣、玩笑，也可称乐于接受玩笑或帮忙的人。','friendly request uses sporting address.','交往'),C('sport.s3','穿戴','The actor sported a bright red scarf at the film premiere.','这位演员在电影首映礼上醒目地戴着一条鲜红围巾。','sport a beard/scarf/watch; sport something proudly','及物动词，指醒目或自豪地穿戴、展示某物。','scarf is noticeably worn.','穿戴')],M('The actor sported a red scarf by hiding it in a drawer and never wearing or showing it.','The actor sported a red scarf by wearing it conspicuously at the premiere.','sport作动词表示穿戴或展示，不是藏起来。','meaning'),[Q(1,'Rowing is a sport because it…','requires physical effort and skill','is a type of legal document','has no physical activity','Sense 1 means an athletic activity.','meaning'),Q(2,'“Be a sport and help us” is a friendly request to…','help in a good-natured way','join an official race','wear a scarf proudly','Sense 2 can refer to a helpful, good-natured person.','context'),Q(3,'The actor sported a scarf means he…','wore or displayed it conspicuously','stored it without showing anyone','used it to measure a boat','Sport as a verb means wear or show.','meaning'),Q(1,'Which phrase uses sport as a verb?','sport a bright new watch','play a sport on Saturday','be a good sport','The first phrase uses the verb sense of wearing/displaying.','grammar')]);
P('sporting','Sporting combines sport + -ing; it means connected with sports or fair-minded and generous in accepting victory or defeat.',[C('sporting.s1','运动','The school opened a sporting facility with courts for tennis and basketball.','学校建成了一处体育设施，设有网球场和篮球场。','sporting events/equipment; sporting activities','形容词，表示与体育运动及比赛活动有关。','courts host athletic activity.','运动'),C('sporting.s2','品格','Although she lost the final, she was sporting enough to congratulate her opponent.','尽管输掉决赛，她仍很有风度地向对手表示祝贺。','a sporting attitude; be sporting about a loss','形容词，也指遵守公平竞争并大度接受输赢。','gracious response to defeat.','品格')],M('She was sporting after losing by refusing to congratulate anyone and accusing every opponent of cheating.','She was sporting after the loss and congratulated her opponent fairly.','公平大度地接受输赢与拒绝祝贺、无端指控相反。','meaning'),[Q(1,'A sporting facility is…','a place connected with athletic activities','a facility for dissolving substances','a theater for a soloist only','Sense 1 means related to sports.','meaning'),Q(2,'A sporting loser is likely to…','accept defeat fairly and congratulate the winner','insult the opponent and deny the result','hide the score','Sense 2 describes fairness and generosity.','context'),Q(1,'Which phrase is natural?','a sporting event','a sportingly event','a sportingness event','Sporting is an adjective modifying event.','grammar'),Q(1,'In “sporting attitude,” sporting describes…','fair-minded acceptance of winning or losing','a type of clothing only','a loud sound','The second sense concerns good sportsmanship.','meaning')]);
P('sportsman','Sportsman combines sport + man; it means a man who takes part in sport and can also refer to someone who behaves fairly in sport and life.',[C('sportsman.s1','运动','The sportsman trained every morning before entering the regional rowing championship.','这名男运动员每天早晨训练，为参加地区赛艇锦标准备。','a professional/amateur sportsman; sportsman competes','名词，指参加体育运动的男性。','man trains for a competition.','运动'),C('sportsman.s2','品格','He was a true sportsman and accepted the referee’s decision without complaint.','他是个真正有体育道德的人，毫无怨言地接受了裁判的判决。','a good/fair sportsman; act like a sportsman','名词也可指在运动和生活中公平待人的人。','accepts decision graciously.','品格')],M('The sportsman showed good sportsmanship by striking the referee after disagreeing with a call.','The sportsman showed good sportsmanship by accepting the referee’s decision calmly.','暴力报复与公平大度的体育道德相反。','meaning'),[Q(1,'A sportsman is, in the basic sense…','a man who takes part in sport','a piece of sports clothing','a woman competing in sport','Sense 1 is the participant meaning.','meaning'),Q(2,'A fair sportsman accepts a referee’s decision…','without unfair behavior or complaint','by attacking the referee','only when he wins','Sense 2 concerns fair behavior.','context'),Q(1,'Which phrase is natural?','a professional sportsman','a sportsman professionaling','a sport manly of professional','Sportsman is the established compound noun.','grammar'),Q(1,'Sportsman is formed from sport and…','man','spore','spot','The word combines sport with man.','word-formation')]);
P('sportswear','Sportswear combines sport + wear; it names clothing designed for athletic activity or casual everyday wear.',C('sportswear.s1','服装','The shop sells lightweight sportswear for running, training, and weekend walks.','这家商店出售适合跑步、训练和周末散步的轻便运动服。','buy/wear sportswear; sportswear for running','名词，不可数，指运动时穿的服装，也常作休闲装。','clothing suits physical activity.','服装'),M('She bought sportswear for the race, choosing a heavy wool evening gown that restricted movement.','She bought flexible sportswear designed for running and training.','限制动作的晚礼服不符合运动服用途。','meaning'),[Q(1,'Sportswear is…','clothing made for exercise or casual day wear','equipment for measuring sound','formal clothing for a wedding only','That is the entry’s clothing sense.','meaning'),Q(1,'Why did the runner buy the lightweight clothing?','It was suitable for running and training.','It was designed to restrict movement.','It was a musical instrument.','The context connects the garments with athletic activity.','context'),Q(1,'Which phrase is natural?','sportswear for training','sportswears for training','sportswearing of training','Sportswear is normally an uncountable noun.','countability'),Q(1,'Sportswear is a compound of sport and…','wear','spore','where','Wear refers to clothing in this compound.','word-formation')]);
P('sportswoman','Sportswoman combines sport + woman; it means a woman who plays sport, often as a serious competitor.',C('sportswoman.s1','运动','The sportswoman represented her country in the 400-metre final.','这名女运动员代表祖国参加了四百米决赛。','a professional/amateur sportswoman; sportswoman competes','名词，指参加体育运动的女性，常指参赛者。','woman competes in an event.','运动'),M('The sportswoman represented her country in the final, but she was a man who had never taken part in sport.','The sportswoman represented her country as a woman competing in the event.','sportswoman指参加体育运动的女性。','distinction'),[Q(1,'A sportswoman is…','a woman who plays or competes in sport','a man who coaches a team','a type of running jacket','That is the source meaning.','meaning'),Q(1,'What did the sportswoman do in the example?','Represented her country in a race final','Measured a sonar signal','Wrote a sonnet about sport','The context shows her as an athlete.','context'),Q(1,'Which plural is correct?','sportswomen','sportswomans','sportswomenses','The compound’s plural changes woman to women.','plural'),Q(1,'Sportswoman combines sport and…','woman','man','wear','The compound identifies a female athlete.','word-formation')]);
P('spot','Spot is of uncertain deeper origin; it can mean a particular place, a small mark, a small amount, or notice something suddenly.',[C('spot.s1','地点','We found a quiet spot beside the river to eat lunch.','我们在河边找到一处安静的地方吃午饭。','a good/quiet spot; a spot for something','名词，指某个具体地点或场所。','place is selected for lunch.','地点'),C('spot.s2','外观','A spot of ink appeared on the white sleeve.','白色袖子上出现了一小块墨渍。','a spot on a surface; spots on the skin','名词，指颜色不同的小斑点、污渍或皮肤丘疹。','mark contrasts with cloth.','外观'),C('spot.s3','数量','There is still a spot of tea left in the bottom of the cup.','杯底还剩一点茶。','a spot of + uncountable noun; a spot of bother','名词，口语中也指少量某物。','small remaining quantity.','数量'),C('spot.s4','观察','The lifeguard spotted a swimmer struggling beyond the buoys.','救生员发现一名游泳者在浮标外挣扎。','spot someone/something; spot a mistake','及物动词，指突然看见、注意到某人或某物。','lifeguard notices swimmer.','观察')],M('The lifeguard spotted a swimmer beyond the buoys by failing to see or notice the person at all.','The lifeguard spotted the swimmer by noticing the person in difficulty.','spot作动词表示发现或注意到，不能是完全没看见。','meaning'),[Q(1,'A quiet spot beside a river is…','a particular place','a stain on clothing','a small amount of tea','Sense 1 means location.','meaning'),Q(2,'A spot of ink on a sleeve is…','a small mark or stain','a quiet place','an athletic event','Sense 2 is a visible mark.','context'),Q(3,'A spot of tea means…','a small amount of tea','a place where tea is grown','a sudden observation','Spot can mean a little of something.','meaning'),Q(4,'The lifeguard spotted a swimmer means the lifeguard…','noticed the swimmer','painted a mark on the swimmer','gave the swimmer a spoonful','Spot as a verb means see or notice.','meaning')]);
P('spotless','Spotless combines spot + -less and means perfectly clean or, figuratively, having no mark against one’s record or reputation.',[C('spotless.s1','清洁','The spotless kitchen had shining counters and not a single crumb on the floor.','这间一尘不染的厨房台面发亮，地板上连一粒碎屑也没有。','spotless room/clothes; keep something spotless','形容词，指极其干净、没有任何污点。','no dirt or mark is visible.','清洁'),C('spotless.s1','声誉','The inspector had a spotless record, with no complaint or disciplinary mark in twenty years.','这名检查员履历清白，二十年来没有投诉或纪律处分。','a spotless record/reputation','形容词比喻指记录或名声没有污点。','record has no adverse mark.','声誉')],M('The spotless kitchen was covered in grease, food scraps, and muddy footprints.','The spotless kitchen was clean, with no dirt or marks.','遍布油污和脚印的厨房不干净。','meaning'),[Q(1,'A spotless kitchen is…','perfectly clean','covered in stains','a quiet lunch location','The first sense means entirely clean.','meaning'),Q(1,'A spotless work record has…','no complaint or disciplinary mark','many unresolved complaints','a spot of tea','The figurative sense refers to a clean record.','context'),Q(1,'Which phrase is natural?','a spotless reputation','a spotlessly reputation','a reputation spotlessless','Spotless is an adjective before reputation.','grammar'),Q(1,'The suffix -less in spotless means…','without','full of','a person who does','Spotless literally means without spots.','word-formation')]);
P('spotlight','Spotlight combines spot + light; it is a lamp directing a strong beam onto a small area, public attention, or the act of drawing that attention.',[C('spotlight.s1','舞台','A spotlight followed the dancer as she crossed the dark stage.','舞者穿过昏暗舞台时，一束聚光灯跟随着她。','shine/focus a spotlight on; under the spotlight','名词，指把强光集中照在一小块区域的灯。','beam tracks performer.','舞台'),C('spotlight.s2','公众','The investigation brought the agency’s safety failures into the spotlight.','这项调查使该机构的安全失误受到公众关注。','in the spotlight; attract public spotlight','名词，指强烈的公众注意或关注。','failures receive public attention.','公众'),C('spotlight.s3','报道','The documentary spotlights the work of volunteer rescue teams.','这部纪录片重点展示了志愿救援队的工作。','spotlight an issue/person; spotlight something','动词，指使某事物受到注意或重点报道。','film draws attention to rescue work.','报道')],M('The documentary spotlighted the rescue team by hiding its work from viewers and avoiding any mention of it.','The documentary spotlighted the rescue team by drawing viewers’ attention to its work.','spotlight作动词表示突出展示，不是刻意隐去。','meaning'),[Q(1,'A stage spotlight is…','a lamp that focuses a strong beam on a small area','a stain on a costume','an instrument that detects spores','Sense 1 is the lighting device.','meaning'),Q(2,'A failure brought into the spotlight receives…','intense public attention','complete secrecy','a layer of soot','Sense 2 is public notice.','context'),Q(3,'A documentary that spotlights volunteers…','draws attention to their work','removes their work from the film','gives them a sports injury','The verb means highlight or feature.','meaning'),Q(1,'Which phrase is natural?','shine a spotlight on the issue','shine a spotlight in the issuely','spotlight to shine at issue','On introduces the area illuminated or highlighted.','collocation')]);
P('spots','Spots is the regular plural of spot; it refers to small round marks, raised skin blemishes, or particular places people use or visit.',[C('spots.s1','外观','The leopard’s spots helped it blend into the broken shadows of the grass.','豹子的斑点帮助它融入草地上斑驳的阴影。','dark/red spots; spots on a surface','复数名词，指表面上颜色或材质不同的小圆点。','pattern consists of marks.','外观'),C('spots.s2','健康','The child developed red spots after touching a plant that caused an allergy.','孩子接触会引起过敏的植物后，身上出现了红疹。','red/white spots; spots on the skin','复数名词，也指皮肤上因疾病或过敏出现的小丘疹。','raised marks follow exposure.','健康'),C('spots.s3','地点','The guide showed visitors the best spots for watching seals along the coast.','导游带游客去海岸线上观赏海豹的最佳地点。','a tourist/picnic spot; favorite spots','复数名词，也指常去或适合某项活动的地方。','locations are chosen for viewing.','地点')],M('The leopard’s spots were smooth areas with exactly the same color as its entire coat.','The leopard’s spots were small marks of a different color from its coat.','spot作为斑点是与周围不同的小标记。','meaning'),[Q(1,'A leopard’s spots are…','small marks of a different color','places to watch seals','a skin allergy in a child','Sense 1 concerns visible markings.','meaning'),Q(2,'Red spots after touching an allergen may be…','raised marks on the skin','places along the coast','a clean record','Sense 2 is a skin blemish.','context'),Q(3,'The best spots for watching seals are…','particular locations suited to viewing','marks on the seals’ skin only','a lamp on a stage','Sense 3 means places or locations.','meaning'),Q(1,'Spots is the plural of…','spot','spotted','spoon','It is formed with regular plural -s.','word-formation')]);
P('spouse','Spouse comes from Old French espous, from Latin sponsus/sponsa, “betrothed”; it means the person to whom someone is married and can refer to either partner.',[C('spouse.s1','家庭','Each spouse signed the mortgage papers before the bank approved the loan.','银行批准贷款前，夫妻双方各自签署了抵押文件。','a spouse; husband or wife/spouse','名词，指某人的丈夫或妻子，即婚姻伴侣。','each partner in marriage signs.','家庭'),C('spouse.s2','法律','The form asks each spouse to list the other partner as an emergency contact.','表格要求每位配偶把另一方列为紧急联系人。','one’s spouse; either spouse','名词，性别中立地指婚姻中的任一方。','either marriage partner may fill in.','法律')],M('She listed her spouse as her emergency contact, although they had never married and were only coworkers.','She listed her spouse as her emergency contact because they were married partners.','spouse指婚姻伴侣，不是普通同事。','meaning'),[Q(1,'A spouse is…','the person someone is married to','a person’s sports coach','an unmarried coworker','That is the basic family meaning.','meaning'),Q(2,'Either spouse may sign the form means…','either partner in the marriage may sign','only the husband may sign','a stranger may sign for them','Spouse can refer to either partner.','context'),Q(1,'Which phrase is natural?','my spouse and I signed','my spouse and me signs','a spouse of I signed','The subject uses the subject pronoun I.','grammar'),Q(1,'The Latin source behind spouse referred to someone…','betrothed','spotted','sound asleep','The word came through French from Latin for a promised marriage partner.','word-formation')]);
P('spout','Spout likely entered English from a Middle Dutch word meaning to spit or spew; it means force liquid out in a stream, speak at length, or a pipe/lip through which liquid pours.',[C('spout.s1','液体','Water spouted from the cracked hose when the pump started.','水泵启动时，水从开裂的软管中喷涌而出。','spout water/flames; spout out of','动词，指液体或其他物质以喷射状涌出。','pressurized water jets out.','液体'),C('spout.s2','器具','The teapot’s spout was chipped, so tea dripped onto the table.','茶壶的壶嘴缺了一块，茶水滴到了桌上。','the spout of a kettle/teapot; pour from the spout','名词，指管道、壶等让液体流出的口或管嘴。','liquid exits at the lip.','器具'),C('spout.s1','言语','The lecturer spouted statistics for an hour without letting the audience ask questions.','讲师滔滔不绝地讲了一个小时的数据，不让听众提问。','spout opinions/nonsense; spout on about','动词也可指没完没了地说，常带厌烦或批评意味。','long one-sided speech.','言语')],M('Water spouted from the cracked hose, but it remained completely dry and released no liquid.','Water spouted from the cracked hose in a strong stream.','喷涌的水意味着液体确实从软管流出。','meaning'),[Q(1,'Water spouted from a hose means it…','shot out in a stream','stayed inside without moving','turned into a solid spool','Spout as a verb describes a jet of liquid.','meaning'),Q(2,'A teapot spout is…','the opening or pipe through which tea pours','the handle used to hold the pot','a sports uniform','Sense 2 names the pouring outlet.','context'),Q(1,'A lecturer who spouts statistics may…','talk at length, possibly tiresomely','remain silent throughout','pour tea from a kettle','This figurative verb sense concerns prolonged speech.','meaning'),Q(1,'Which phrase is natural?','the spout of the kettle','the kettle spoutly of','the spout to pourly kettle','Of connects the pouring part with its container.','grammar')]);
P('sprain','Sprain has an uncertain deeper origin; as a noun it is an injury to a joint caused by sudden twisting, and as a verb it means injure a joint in that way.',[C('sprain.s1','健康','The runner rested her ankle after a sprain caused it to swell.','脚踝扭伤并肿起来后，跑步者休息了。','an ankle/wrist sprain; suffer a sprain','名词，指关节突然扭转造成的肿痛损伤。','joint is swollen after injury.','健康'),C('sprain.s2','健康','He sprained his wrist when he slipped on the wet steps.','他在湿台阶上滑倒时扭伤了手腕。','sprain an ankle/wrist; badly sprain','及物动词，指突然扭伤脚踝、手腕等关节。','twist damages a joint.','健康')],M('She sprained her ankle but suffered no joint injury, swelling, or pain.','She sprained her ankle when it twisted suddenly and became painful and swollen.','sprain指关节扭伤，通常伴随疼痛或肿胀。','meaning'),[Q(1,'An ankle sprain is…','a joint injury caused by a sudden twist','a fracture of every bone in the leg','a sports uniform','Sense 1 names the injury.','meaning'),Q(2,'He sprained his wrist means he…','twisted and injured the joint','broke the wrist deliberately with a tool','sprayed water on his arm','Sense 2 is the verb use.','context'),Q(1,'Which phrase is natural?','sprain your wrist','sprain to your wrist','sprainedly your wrist','Sprain takes the injured joint as its direct object.','grammar'),Q(1,'The deeper origin of sprain is…','uncertain','certainly from spring water','certainly a Latin word for spouse','No precise earlier derivation is asserted.','word-formation')]);
P('sprawl','Sprawl is of uncertain deeper origin; as a verb it means sit or lie with limbs loosely extended, spread untidily over a wide area, and as a noun it can name that posture or an untidy spread of buildings.',[C('sprawl.s1','姿势','After the long hike, he sprawled across the sofa with his arms and legs stretched out.','长途徒步后，他四肢摊开，横躺在沙发上。','sprawl on/across a surface; sprawl out','不及物动词，指坐或躺时四肢松散伸展开。','limbs spread loosely.','姿势'),C('sprawl.s2','城市','New housing sprawled across the valley without a coordinated plan.','新住宅区毫无统筹地蔓延到整个山谷。','sprawl across/into; urban sprawl','动词，指建筑或区域杂乱无序地向大片地域扩张。','development spreads untidily.','城市'),C('sprawl.s3','城市','The town’s suburban sprawl has replaced much of the nearby farmland.','城镇向郊区无序扩张，附近大部分农田已被取代。','urban/suburban sprawl; a sprawling area','名词，指杂乱蔓延的建筑区或摊开的姿势。','spread of buildings replaces fields.','城市')],M('The town’s urban sprawl was a compact cluster of buildings confined to one small block.','The town’s urban sprawl spread untidily across a wide area.','sprawl指无序扩散，而非紧凑集中。','meaning'),[Q(1,'He sprawled across the sofa means he…','lay with his limbs stretched out loosely','sat upright with his arms folded','ran a short race','Sense 1 is a relaxed extended posture.','meaning'),Q(2,'Housing sprawled across the valley means it…','spread over a wide area without a tidy plan','stayed inside one small building','was wound onto a spool','Sense 2 concerns untidy expansion.','context'),Q(3,'Suburban sprawl is…','a widespread, untidy spread of buildings','a single isolated cottage','a sudden joint injury','The noun names the extended built-up area.','meaning'),Q(1,'Which phrase is natural?','sprawl across the valley','sprawl the valley acrossly','sprawl at valley of across','Across indicates the area over which development spreads.','grammar')]);
P('spray','Spray is of uncertain deeper origin; it names liquid in tiny airborne drops or the container/liquid dispensed as a mist, and the verb means send droplets onto a surface.',[C('spray.s1','天气','A fine spray from the waterfall cooled the hikers standing nearby.','瀑布飘来的细小水雾让站在附近的徒步者凉爽了一些。','a spray of water; sea spray','名词，指飞散在空气中的细小液滴或水花。','tiny droplets drift through air.','天气'),C('spray.s2','用品','She used an insect spray to protect the seedlings from aphids.','她用杀虫喷剂保护幼苗不受蚜虫侵害。','aerosol/insect spray; a can of spray','名词，指喷出的雾状液体或装这种液体的容器。','container dispenses pesticide mist.','用品'),C('spray.s3','操作','Spray the leaves lightly with water every morning.','每天早晨给叶片轻轻喷些水。','spray something with; spray water onto','及物动词，指把液体以小液滴形式喷到表面。','water droplets land on leaves.','操作')],M('She sprayed the leaves by placing them in a dry room and keeping all water away.','She sprayed the leaves with a fine mist of water.','spray leaves需要把液滴喷到叶面上。','meaning'),[Q(1,'Waterfall spray is…','fine droplets carried through the air','a solid block of ice','a joint injury','Sense 1 is liquid dispersed in tiny drops.','meaning'),Q(2,'An insect spray is…','a mist or container used to dispense pesticide','a type of sports clothing','a natural spring','Sense 2 names the product or its container.','context'),Q(3,'To spray the leaves is to…','send tiny drops of liquid onto them','wipe them with a dry cloth','wind them around a spool','Sense 3 is the action.','meaning'),Q(1,'Which construction is natural?','spray the leaves with water','spray water to the leaves withly','sprayed leaves at watering','With introduces the liquid used.','grammar')]);
P('sprayer','Sprayer is formed from spray + -er; it names a tool, gun, or machine that forces liquid out as a mist.',C('sprayer.s1','工具','The gardener filled the sprayer with water and misted the seedlings.','园丁把水装进喷雾器，给幼苗喷上水雾。','a garden/paint sprayer; fill a sprayer with','名词，指把液体压成雾状喷出的工具或机器。','device emits droplets.','工具'),M('The sprayer watered the seedlings by keeping all liquid sealed inside its tank.','The sprayer watered the seedlings by forcing water out as a mist.','喷雾器必须把液体喷出才能完成喷洒。','meaning'),[Q(1,'A sprayer is…','a tool or machine that emits liquid as a mist','a container that can never release liquid','a device for measuring time','That is the entry’s sense.','meaning'),Q(1,'How did the gardener water the seedlings?','By misting them with a filled sprayer','By hiding the water in a cupboard','By using a spoon to plant them','The sprayer sends fine droplets onto plants.','context'),Q(1,'Which phrase is correct?','fill the sprayer with water','fill the sprayer waterly','fill with water the sprayer of','With introduces what goes into the sprayer.','grammar'),Q(1,'Sprayer is formed from spray plus…','-er','-ity','-less','The suffix names the device or person that sprays.','word-formation')]);
P('spread','Spread comes from Old English sprǣdan, “extend, stretch out”; it means open or cover a wider area, transmit or apply something, and can name extent or a soft food for bread.',[C('spread.s1','空间','She spread the map across the table so everyone could see the route.','她把地图铺在桌上，让大家都能看清路线。','spread something out/across; spread a blanket','及物动词，指展开或铺开某物使其覆盖更大面积。','map opened across surface.','空间'),C('spread.s2','传播','The rumor spread to neighboring towns before officials could confirm the facts.','官方尚未核实事实，谣言就传到了邻近城镇。','spread to/through; spread a message; spread butter','动词也指信息、疾病等传开，或把软食涂在表面上。','rumor reaches more places.','传播'),C('spread.s3','食品','A thin spread of cream cheese covered each piece of toast.','每片吐司上都薄薄地抹了一层奶油奶酪。','a spread for bread; a wide spread','名词可指软质涂抹食品，也可指范围或传播程度。','soft food coats bread.','食品')],M('She spread the map across the table by folding it into a tiny square and keeping it closed.','She spread the map across the table so the route was visible.','展开地图意味着打开并铺开，而不是折叠收起。','meaning'),[Q(1,'She spread the map across the table means she…','opened it over a wider surface','folded it into a small closed square','sent it to another town','Sense 1 means open or extend over an area.','meaning'),Q(2,'A rumor spread to neighboring towns means it…','reached more people or places','was applied to toast','was kept secret in one house','Sense 2 is transmission.','context'),Q(3,'A cream-cheese spread is…','a soft food put on bread','a folded map','a sudden storm','Sense 3 is the food item.','meaning'),Q(1,'Which phrase is natural?','spread butter on the toast','spread the butter at the toastly','spread to butter the toast','On introduces the surface receiving the food.','grammar')]);
P('spread to','Spread to is the verb spread followed by to; it describes an effect, infection, or information reaching additional people or places, and can describe light or smell traveling through air.',[C('spread to.s1','传播','The infection began in one ward and spread to two other units.','感染从一个病房开始，后来蔓延到另外两个病区。','spread to + people/places; disease spreads to','动词短语，表示从起点影响到更多人或更大区域。','infection reaches other units.','传播'),C('spread to.s2','感官','The smell of fresh bread spread to the upstairs hallway.','新鲜面包的香味飘到了楼上的走廊。','light/smell spread to a place','动词短语也可指气味或光线在空气中传播到另一地点。','scent reaches corridor.','感官')],M('The infection spread to two units, but it never reached anyone or any place outside the original ward.','The infection spread to two other units beyond the original ward.','spread to描述影响到新地点，与始终局限原地相反。','meaning'),[Q(1,'An infection that spread to other units…','reached additional areas','remained only in its original ward','was wound onto a reel','Sense 1 is transmission to new places.','meaning'),Q(2,'A smell that spread to the hallway…','traveled through the air and reached it','was confined to the oven','was stored in a sports bag','Sense 2 applies to scent moving to a location.','context'),Q(1,'Which phrase is standard?','The fire spread to nearby buildings.','The fire spread nearby buildings to.','The fire spread at the buildings toly.','To introduces the destination affected.','grammar'),Q(1,'In this phrase, to marks…','the place or group newly reached','the original source only','the tool used to spray liquid','Spread to requires a destination.','meaning')]);
P('spree','Spree is an informal word of uncertain origin; it means a short period of uncontrolled enjoyment or a rapid series of reckless or criminal acts.',[C('spree.s1','消费','After payday, he went on a spending spree and bought several things he did not need.','发工资后，他大肆购物，买了好几样并不需要的东西。','go on a spending/shopping spree','名词，指一段短时间内放纵地做某事，如大量花钱或饮酒。','shopping is uncontrolled and brief.','消费'),C('spree.s2','犯罪','Police investigated a spree of robberies committed across three towns in one night.','警方调查了一夜之间在三个城镇接连发生的一系列抢劫案。','a crime/robbery spree; a spree of + acts','名词，也指短时间内连续发生的一串犯罪或鲁莽行为。','several crimes occur in quick succession.','犯罪')],M('He went on a spending spree by refusing to buy anything throughout the entire year.','He went on a spending spree, making many unnecessary purchases in a short time.','spree表示短期内连续放纵消费，不是全年不买东西。','meaning'),[Q(1,'A spending spree is…','a short period of uncontrolled shopping','a long period of saving every penny','a sport requiring a sprint','Sense 1 concerns excessive activity for a short time.','meaning'),Q(2,'A spree of robberies means…','a series of robberies in a short period','one legal purchase','a crime-free year','Sense 2 names repeated reckless or criminal acts.','context'),Q(1,'Which phrase is natural?','go on a shopping spree','go at shopping spreely','spree on go to shopping','Go on a spree is the standard phrase.','collocation'),Q(1,'The deeper origin of spree is…','uncertain','certainly Latin for a joint injury','certainly a compound of sport and wear','Its earlier word history is not firmly established.','word-formation')]);
P('spring','Spring comes from Old English springan, “leap, burst forth”; it names the season, a coil that returns to shape, a natural water source, or the sudden action of jumping/appearing.',[C('spring.s1','季节','Wildflowers appear in spring after the last frost has passed.','最后一场霜冻过去后，春天会开出野花。','in spring; spring flowers','名词，指冬季和夏季之间的春季。','flowers bloom in season.','季节'),C('spring.s2','机械','A broken spring made the old mattress sag in the middle.','弹簧坏了，旧床垫中间便塌了下去。','a coil/metal spring; spring back','名词，指受压后能够恢复形状的金属线圈。','coil supports mattress and rebounds.','机械'),C('spring.s3','地理','A cold spring rises from the hillside and feeds the stream below.','山坡上涌出一眼冷泉，为下方的小溪供水。','a natural/hot spring; a spring of water','名词，指地下水自然涌出地表的泉眼或水源。','water emerges from ground.','地理'),C('spring.s4','动作','The cat sprang onto the windowsill when it heard the bird.','听到鸟叫后，猫一下子跳上了窗台。','spring up/from/onto; spring to mind','动词，指突然跳起、出现或冒出。','cat jumps suddenly.','动作')],M('A metal spring returned to its original length after being pressed, but it remained permanently stretched and could not rebound.','The metal spring returned to its original shape after being pressed.','spring作为弹簧的特征是受压后恢复形状。','meaning'),[Q(1,'Wildflowers appearing in spring refers to…','the season between winter and summer','a coiled metal part','a water source','Sense 1 names the season.','meaning'),Q(2,'A mattress spring is…','a coil that can return to shape','a stream from a hillside','a sudden jump','Sense 2 is the mechanical object.','context'),Q(3,'A natural spring is…','water emerging from the ground','the season after winter','a bed component','Sense 3 names a water source.','meaning'),Q(4,'The cat sprang onto the sill means it…','jumped suddenly','grew a new water source','became a metal coil','Sense 4 is the verb meaning leap.','meaning')]);
P('springboard','Springboard combines spring + board; it is a board that adds bounce for a dive or vault, and figuratively a starting point for progress.',[C('springboard.s1','体育','The diver pushed off the springboard and entered the pool headfirst.','跳水运动员蹬离跳板，头朝下入水。','dive from a springboard; springboard diving','名词，指能产生弹力、供跳水或跳跃使用的板。','board propels diver upward.','体育'),C('springboard.s1','比喻','The internship became a springboard for her career in environmental research.','这次实习成了她投身环境研究事业的起点。','a springboard to/for a career; use as a springboard','名词比喻指帮助后续发展或成功的起点。','experience launches next career step.','比喻')],M('The internship was a springboard for her career because it ended all opportunities for further work.','The internship was a springboard for her career because it opened a path to research work.','springboard比喻为发展提供起点，不是封闭后续机会。','meaning'),[Q(1,'A diving springboard is…','a board that provides bounce for a dive','a flat mat with no rebound','a natural spring of water','Sense 1 is the sports equipment.','meaning'),Q(1,'The internship became a springboard for a career means it…','helped launch further progress','prevented any future opportunity','was a piece of diving equipment','The figurative sense is a starting point for advancement.','context'),Q(1,'Which phrase is natural?','a springboard to a new career','a springboard at careerly new','springboard career from for the','To/for can introduce the next goal.','grammar'),Q(1,'Springboard is formed from spring and…','board','spore','sport','It is a compound naming a bouncing board.','word-formation')]);
P('springtime','Springtime combines spring + time and means the period of the year when spring occurs.',C('springtime.s1','季节','The orchard is busiest in springtime, when the trees blossom and bees return.','春天果园最忙，树木开花，蜜蜂也回来了。','in springtime; early springtime','名词，指一年中春季的时段。','blossoming marks the season.','季节'),M('The orchard’s springtime blossom appeared in the middle of winter after all the trees had died.','The orchard’s springtime blossom appeared as the trees came back into bloom.','springtime是春季，不是严冬；枯死的树也不会开花。','meaning'),[Q(1,'Springtime is…','the period of year when spring occurs','the season after autumn','a metal coil in a mattress','That is the word’s meaning.','meaning'),Q(1,'Why is the orchard busy in springtime?','Trees blossom and bees return.','The lake is frozen all year.','The trees are permanently dead.','The example connects springtime with seasonal bloom.','context'),Q(1,'Which phrase is correct?','birds return in springtime','birds return springtimely','springtime the birds returns in','In can introduce the season.','grammar'),Q(1,'Springtime combines spring with…','time','board','light','The compound refers to the time of spring.','word-formation')]);
P('springwater','Springwater combines spring + water and means water that issues naturally from an underground spring.',C('springwater.s1','饮水','The hikers filled their bottles with clear springwater from the protected source.','徒步者从受保护的泉眼取了清澈的泉水装进水瓶。','bottled/natural springwater; source of springwater','名词，不可数，指从地下天然泉眼涌出的水。','water comes from a natural spring.','饮水'),M('They called the water springwater even though it came from a treated city pipe and no spring.','They called it springwater because it flowed naturally from a hillside spring.','springwater的来源是天然泉眼，不是城市水管。','distinction'),[Q(1,'Springwater is water…','issuing from a natural spring','made by melting a metal coil','stored only in a sports bottle','That is the source sense.','meaning'),Q(1,'Where did the hikers fill their bottles?','At a protected natural spring','From a dry sidewalk','From a teapot spout in town','The example names a spring as the source.','context'),Q(1,'Which phrase is natural?','a bottle of springwater','a springwaters bottle','a springwaterful of bottle','Springwater is usually an uncountable substance noun.','countability'),Q(1,'Springwater is a compound of spring and…','water','time','board','The compound identifies water by its natural source.','word-formation')]);
P('sprinkle','Sprinkle comes from Middle English, likely from a frequentative form related to Old English sprengan; it means scatter small drops or pieces, be scattered sparsely, or a small scattered amount/light rain.',[C('sprinkle.s1','烹饪','Sprinkle a little salt over the tomatoes just before serving.','上菜前在番茄上撒少许盐。','sprinkle something over/on; sprinkle with sugar','及物动词，指把小颗粒或液滴零散地撒在表面上。','small grains scattered on food.','烹饪'),C('sprinkle.s2','天气','Light rain sprinkled the coast throughout the afternoon.','整个下午，海岸间间歇地下着小雨。','it sprinkled; rain sprinkled across','动词也可表示某处有零星分布的东西，或下小雨。','light drops fall intermittently.','天气'),C('sprinkle.s3','数量','A sprinkle of cinnamon was enough to flavor the porridge.','撒一点肉桂就足以给燕麦粥调味。','a sprinkle of + powder; a sprinkle of rain','名词，指零星撒上的少量东西或一阵小雨。','small quantity seasons porridge.','数量')],M('She sprinkled cinnamon over the porridge by pouring an entire jar into one spot.','She sprinkled a small amount of cinnamon evenly over the porridge.','sprinkle表示零散少量地撒，不是整罐集中倒入。','meaning'),[Q(1,'To sprinkle salt over tomatoes is to…','scatter small grains across them','dissolve the tomatoes in salt','hide the salt in a jar','Sense 1 describes scattering small pieces.','meaning'),Q(2,'If it sprinkled along the coast, there was…','light, scattered rain','a heavy continuous flood','a sports competition','Sense 2 can describe light rain.','context'),Q(3,'A sprinkle of cinnamon is…','a small amount scattered on food','a full jar of powder','a metal spring','Sense 3 is the noun for a little scattered amount.','meaning'),Q(1,'Which construction is natural?','sprinkle sugar over the fruit','sprinkle the fruit withly sugar','sprinkling to sugar over the fruit at','Over identifies the surface receiving the sugar.','grammar')]);
P('sprint','Sprint entered English in the 19th century for a short, fast race; it is a brief maximal-speed run or the act of running quickly for a short distance.',[C('sprint.s1','田径','The 100-metre sprint ended in less than eleven seconds.','这场一百米短跑不到十一秒就结束了。','a short-distance sprint; win the sprint','名词，指全力快速奔跑的短距离比赛或冲刺。','race is short and fast.','田径'),C('sprint.s2','动作','She sprinted to the platform when she heard the train announcement.','听到列车通知后，她冲刺跑向站台。','sprint to/toward; sprint the final stretch','动词，指在短距离内尽可能快地跑。','runner moves quickly a short distance.','动作')],M('She sprinted to the platform by walking slowly and stopping every few metres.','She sprinted to the platform by running as fast as she could for the short distance.','sprint表示短距离快速跑，不是缓慢步行。','meaning'),[Q(1,'A 100-metre sprint is…','a short race run as fast as possible','a long walk at an easy pace','a game played with a ball only','That is the athletic sense.','meaning'),Q(2,'She sprinted to the platform means she…','ran very fast for a short distance','waited at home','sprinkled water on the train','Sprint as a verb means run at top speed briefly.','context'),Q(1,'Which phrase is natural?','sprint toward the finish line','sprint the finish line towardly','sprintedly toward finish','Toward introduces the destination.','grammar'),Q(1,'Sprint entered English as a term for…','a short, fast race','a quiet spring season','a type of spoon','Its early use was in short-distance racing.','word-formation')]);
P('sprite','Sprite comes from Middle English spirit, shortened from Old French esprit and Latin spiritus; it can mean a small supernatural being or a small movable computer-game image.',[C('sprite.s1','民间故事','A sprite appeared in the forest clearing and vanished before the travelers could approach.','一个小精灵出现在林间空地上，旅人还没走近就消失了。','a forest/water sprite; sprite from folklore','名词，指传说中体形很小的超自然精灵。','magical being appears in tale.','民间故事'),C('sprite.s2','计算机','The game engine redraws each sprite as the player moves through the scene.','玩家在场景中移动时，游戏引擎会重新绘制每个精灵图。','a game/screen sprite; animated sprite','名词，指电脑或电子游戏屏幕上可移动的小图像。','image moves on screen.','计算机')],M('The game sprite was a supernatural creature in a forest story, not a graphic image displayed on screen.','The game sprite was a small graphic that moved across the screen.','电子游戏语境中的sprite指屏幕图像。','distinction'),[Q(1,'A forest sprite is…','a small supernatural being in a story','a computer image only','a short-distance race','Sense 1 is the folklore meaning.','meaning'),Q(2,'A game sprite is…','a small image that moves across a screen','a forest spirit visible to hikers','a metal spring','Sense 2 is the computing term.','context'),Q(1,'Which phrase is natural?','an animated sprite on screen','a sprite screenly animatedly','a screen to sprite at animated','On screen identifies the display location.','grammar'),Q(1,'Sprite developed from a shortened form of…','spirit','spring','spray','The word came from spirit via French esprit.','word-formation')]);
P('sprout','Sprout comes from Old English sprūtan, “to shoot, grow”; it is a young plant shoot and the verb means begin to grow or produce new shoots.',[C('sprout.s1','植物','A green sprout emerged from each seed after three days in the warm soil.','种子在温暖的土壤里三天后都长出了绿色嫩芽。','a seedling/sprout; bean sprouts','名词，指从种子、球茎或枝条长出的嫩芽。','new shoot emerges.','植物'),C('sprout.s2','植物','The potatoes began to sprout in the dark cupboard and were no longer suitable for storage.','土豆在黑暗的橱柜里开始发芽，不再适合储存。','seeds sprout; sprout leaves/shoots','动词，指种子开始生长或植物长出新芽。','potatoes develop shoots.','植物')],M('The bean began to sprout but produced no new growth from its seed.','The bean began to sprout, sending a small shoot out of the seed.','sprout表示开始生长或长出嫩芽。','meaning'),[Q(1,'A sprout is…','a young shoot from a seed or plant','a fully grown forest tree','a fast race','Sense 1 is the new plant growth.','meaning'),Q(2,'Potatoes that sprout have…','begun to produce new shoots','turned into springwater','become completely spotless','Sense 2 is the verb meaning begin to grow.','context'),Q(1,'Which sentence is natural?','Seeds sprout in warm soil.','Seeds sproutly in warm soil.','Seeds are a sprout in warmly.','Sprout is used as an intransitive verb for germination.','grammar'),Q(1,'Sprout comes from Old English sprūtan, meaning…','shoot or grow','spit or pour','run a race','The old verb referred to shooting or growing.','word-formation')]);
P('spruce','The name spruce for the evergreen tree may be connected with “Pruce” (Prussia); the adjective meaning neat and smart has a separate, uncertain history.',[C('spruce.s1','植物','A tall spruce shaded the cabin and kept snow from piling against the door.','一棵高大的云杉为小屋遮阴，也挡住了堆向门口的雪。','a spruce forest/tree; spruce needles','名词，指一种针叶常绿乔木。','conifer shelters cabin.','植物'),C('spruce.s1','外表','He looked spruce in a freshly pressed jacket and polished shoes.','他穿着熨平的夹克和擦亮的鞋子，看起来整洁利落。','look spruce; spruce clothes','形容词，指衣着或外表整洁漂亮。','neat clothes give tidy appearance.','外表')],M('He looked spruce in his wrinkled, muddy clothes and uncombed hair.','He looked spruce in neat, freshly pressed clothes.','spruce形容外表整洁，不是凌乱泥泞。','meaning'),[Q(1,'A spruce is…','an evergreen coniferous tree','a garden spray tool','a human joint','Sense 1 names the tree.','meaning'),Q(1,'A person who looks spruce appears…','neat and smart','unwashed and untidy','deeply asleep','The adjective describes a tidy appearance.','context'),Q(1,'Which phrase is natural?','a spruce tree near the cabin','a sprucely tree near the cabin','a tree spruceful near cabin','Spruce is a noun before tree in the first sense.','grammar'),Q(1,'The tree name spruce may relate to an old word for…','Prussia','a spoon','a short race','Its exact derivation is cautiously linked with “Pruce.”','word-formation')]);
P('spud','Spud is an informal English word of uncertain origin for a potato.',C('spud.s1','饮食','We roasted a spud in the fire and split it open with a fork.','我们在火里烤了一个土豆，再用叉子把它剖开。','baked/roasted spud; a sack of spuds','名词，非正式说法，指土豆。','roasted vegetable is potato.','饮食'),M('He ordered a spud, which the menu defined as a type of flat sea fish.','He ordered a spud, an informal name for a potato.','spud是土豆的非正式名称，不是鱼名。','distinction'),[Q(1,'A spud is an informal name for…','a potato','a springboard','a small metal spool','That is the source sense.','meaning'),Q(1,'What did they roast in the fire?','A potato','A songbird','A sorceress','The example uses spud for the vegetable.','context'),Q(1,'Which phrase is natural?','a baked spud','a baked spudsly','spud of baked a','Spud is a count noun for one potato.','grammar'),Q(1,'The deeper origin of spud is…','uncertain','certainly Latin for “alone”','certainly from sport and wear','The informal word’s earlier history is unsettled.','word-formation')]);
P('spur','Spur comes from Old English spura, a pointed device worn on a rider’s boot; it also means an incentive and as a verb means encourage or urge forward.',[C('spur.s1','骑马','The rider touched the horse with a spur to urge it forward.','骑手用马刺轻触马匹，催它向前。','a riding spur; spur a horse','名词，指骑手靴跟上用于催马的尖刺，也可作动词策马。','boot device prompts horse.','骑马'),C('spur.s2','动力','The award gave her the spur she needed to finish the research.','这项奖励给了她所需的动力，让她完成研究。','a spur to action; a spur for growth','名词，比喻指促使某人行动的刺激或动力。','award motivates completion.','动力'),C('spur.s3','行动','The public criticism spurred the council to publish the safety report.','公众批评促使市议会公布了安全报告。','spur someone to do; spur growth/action','及物动词，指激励或推动某人采取行动。','criticism prompts publication.','行动')],M('The award was a spur to her research, but it discouraged her from continuing and gave no motivation.','The award was a spur to her research and encouraged her to continue.','spur作比喻指推动行动的刺激或动力。','meaning'),[Q(1,'A riding spur is…','a pointed device worn on a boot to urge a horse','a spring that supports a mattress','a small amount of sugar','Sense 1 is the riding equipment.','meaning'),Q(2,'An award can be a spur to research by…','providing motivation','stopping all further work','covering the desk with spots','Sense 2 is a figurative incentive.','context'),Q(3,'Criticism spurred the council to publish a report means it…','encouraged or prompted publication','prevented publication permanently','made the report a springboard','Spur as a verb means prompt someone to act.','meaning'),Q(1,'Which construction is correct?','spur someone to act','spur someone for actly','spur to someone acting at','To introduces the action prompted.','grammar')]);
P('spurge','Spurge is a plant name from Middle English and Old French forms related to Latin expurgare, “to purge”; many spurges have irritating or toxic milky sap.',C('spurge.s1','植物','The gardener wore gloves while removing spurge because its milky sap can irritate skin.','园丁清除大戟属植物时戴着手套，因为它的乳白色汁液可能刺激皮肤。','a spurge plant; milkweed spurge','名词，指大戟科的一类植物，其中许多种含有有毒乳汁。','plant sap prompts protective gloves.','植物'),M('The gardener handled the spurge’s toxic sap with bare hands because the plant contains no irritating liquid.','The gardener wore gloves because some spurge sap can irritate the skin.','许多大戟属植物的乳汁有刺激性，徒手接触并不安全。','meaning'),[Q(1,'Spurge is…','a plant in a family whose species often have milky sap','a tool for spraying water','a fast running race','That is the botanical sense.','meaning'),Q(1,'Why did the gardener wear gloves?','Some spurge sap can irritate the skin.','The plant is a sports uniform.','The sap was springwater for drinking.','The context identifies a skin hazard.','context'),Q(1,'Which phrase is natural?','remove the spurge plant carefully','remove the spurgeful plant carefully','spurge to remove carefully at','Spurge is the name of the plant being removed.','grammar'),Q(1,'The name spurge is historically related to a Latin verb meaning…','purge','sing','jump','Its word history is connected to Latin expurgare.','word-formation')]);
P('spurn','Spurn comes from Old English speornan, “kick, trample”; it means reject an offer, person, or belief with contempt.',C('spurn.s1','态度','The committee spurned the offer because it demanded unfair conditions.','委员会轻蔑地拒绝了这项条件不公平的提议。','spurn an offer/advance; spurn someone’s advice','及物动词，指轻蔑或鄙夷地拒绝。','offer is rejected contemptuously.','态度'),M('She spurned the proposal with gratitude and accepted it eagerly.','She spurned the proposal with contempt and refused to accept it.','spurn表示轻蔑拒绝，与感激地接受相反。','distinction'),[Q(1,'To spurn an offer is to…','reject it with contempt','accept it gratefully','spread it over a surface','That is the source meaning.','meaning'),Q(1,'Why did the committee spurn the offer?','Its conditions were unfair.','It was a clean and fair contract.','It was a springtime picnic.','The example gives a reason for rejection.','context'),Q(1,'Which phrase is natural?','spurn someone’s advice','spurn to someone’s advice','spurningly advice someone','Spurn takes the rejected thing as a direct object.','grammar'),Q(1,'Spurn’s Old English ancestor meant…','kick or trample','sprout or grow','wind onto a spool','The figurative sense developed from rejecting as if kicking away.','word-formation')]);
P('spurt','Spurt is of uncertain deeper origin; as a verb it means burst out in a stream or increase suddenly, and as a noun it is a short burst of speed or activity.',C('spurt.s1','变化','Oil spurted from the damaged pipe when the valve was opened.','阀门打开时，油从损坏的管道里喷涌出来。','spurt out/from; spurt suddenly','动词，指液体突然成股喷出，也指数量或活动猛增。','fluid bursts from pipe.','变化'),M('Oil spurted from the pipe in a sudden jet, but no liquid came out.','Oil spurted from the pipe in a sudden stream.','喷涌意味着液体突然喷出，不是完全没有液体。','meaning'),[Q(1,'Oil spurted from the pipe means it…','burst out in a sudden stream','remained still inside the pipe','became a solid coil','Spurt as a verb describes a sudden jet.','meaning'),Q(1,'A sudden spurt in applications is…','a rapid short increase','a slow decline over many years','a light rain shower','Spurt can also describe abrupt growth.','context'),Q(1,'Which sentence uses spurt as a noun?','He made a final spurt toward the finish.','He spurt the pipe yesterday.','The spurted is a pipe.','A spurt can be a brief burst of speed.','grammar'),Q(1,'The deeper origin of spurt is…','uncertain','definitely Latin for spouse','certainly from springtime','Its earlier history is not firmly established.','word-formation')]);
P('sputter','Sputter is imitative of short spitting sounds; it describes an engine making irregular noises or a person speaking in broken bursts when angry or shocked.',[C('sputter.s1','机械','The old engine sputtered twice and stopped at the traffic light.','旧发动机断断续续地噼啪响了两声，随后在红灯前熄火。','an engine sputters; sputter to a stop','动词，尤指引擎停转前发出断续的噼啪声。','engine falters and stops.','机械'),C('sputter.s2','言语','“That is not what I said,” he sputtered, too angry to finish the sentence.','他气得话都说不完整，结结巴巴地说：“我不是那么说的。”','sputter in anger; sputter out words','动词，指因愤怒、震惊等结结巴巴地说话。','anger interrupts fluent speech.','言语')],M('The engine sputtered smoothly and silently for hours without missing a beat.','The engine sputtered with irregular popping sounds and then stopped.','稳定、安静地运转不是断续噼啪作响。','meaning'),[Q(1,'An engine that sputters may…','make irregular small popping sounds before stopping','run smoothly and silently','release a clear speech','Sense 1 describes an engine faltering.','meaning'),Q(2,'He sputtered in anger because he…','spoke in short broken bursts','sang calmly for an hour','could not hear the engine','Sense 2 describes disrupted speech.','context'),Q(1,'Which phrase is natural?','the engine sputtered to a stop','the engine sputteredly stopped to','the sputter engine had stoppedly','Sputter to a stop is a common pattern.','grammar'),Q(1,'Sputter is an example of a word shaped by…','imitation of short spitting sounds','a Latin plural ending','a compound with spring','Its sound pattern echoes the noise it describes.','word-formation')]);
P('sputum','Sputum comes from Latin sputum, “spit,” from spuere, “to spit”; it is material coughed up from the respiratory tract for medical examination.',C('sputum.s1','医学','The clinic sent a sputum sample to the laboratory to test for infection.','诊所把一份痰液样本送到实验室检测感染。','sputum sample/test; cough up sputum','名词，不可数，指从呼吸道咳出的痰液。','sample is coughed up for testing.','医学'),M('The clinic tested sputum, a liquid swallowed from the stomach rather than coughed up from the respiratory tract.','The clinic tested sputum coughed up from the respiratory tract.','sputum指呼吸道咳出的痰，不是胃里的内容物。','distinction'),[Q(1,'Sputum is…','material coughed up from the respiratory tract','saliva swallowed from the stomach','a medicinal spray','That is the medical sense.','meaning'),Q(1,'Why did the clinic send the sample to a lab?','To test it for infection','To use it as sportswear','To measure its musical pitch','Sputum samples can be examined medically.','context'),Q(1,'Which phrase is natural?','a sputum sample','a sputums sample','a sputumful sample of','Sputum is an uncountable medical noun.','countability'),Q(1,'The Latin source sputum meant…','spit','spring','sound','It comes from Latin spuere, “to spit.”','word-formation')]);
P('spy','Spy comes through Old French espier, likely from a Germanic verb meaning “watch, observe”; it names a secret information-gatherer, the act of secret surveillance, or suddenly seeing something.',[C('spy.s1','情报','The spy sent the company’s secret plans to a rival firm.','这名间谍把公司的机密计划发给了一家竞争对手。','a government/company spy; work as a spy','名词，指秘密为政府或公司收集信息的人。','information is gathered secretly.','情报'),C('spy.s2','监视','The guards spied on the visitors from the control room.','警卫在控制室里暗中监视访客。','spy on someone; spy for a government','动词，指暗中观察或从事间谍活动。','watching is concealed.','监视'),C('spy.s3','发现','From the hilltop, we spied a lighthouse far across the bay.','我们从山顶远远看见海湾对岸有一座灯塔。','spy someone/something in the distance','书面动词，指突然或远远看见某物。','lighthouse is noticed from afar.','观察')],M('The spy openly published every secret before gathering information in secret.','The spy secretly collected information and sent it to a rival.','间谍的核心工作是秘密收集信息。','meaning'),[Q(1,'A company spy is someone who…','secretly gathers information for an organization','repairs the company’s windows','writes a sonnet for employees','Sense 1 is the information-gatherer.','meaning'),Q(2,'The guards spied on visitors means they…','watched them secretly','welcomed them publicly','sprayed water over them','Sense 2 is secret observation.','context'),Q(3,'We spied a lighthouse means we…','suddenly noticed it, perhaps from a distance','built it ourselves','heard it making a noise','Sense 3 means catch sight of.','meaning'),Q(1,'Which phrase is natural?','spy on the visitors','spy the visitors on','spy to the visitors','On introduces the people secretly watched.','grammar')]);
P('spyglass','Spyglass combines spy + glass and names a small handheld one-tube telescope for viewing distant objects.',C('spyglass.s1','航海','The captain raised a spyglass to inspect the approaching sail beyond the reef.','船长举起单筒望远镜，查看礁石外驶近的帆船。','look through a spyglass; captain’s spyglass','名词，指手持、单筒的小型望远镜。','device magnifies distant ship.','航海'),M('The captain used a spyglass to inspect the sail by looking at it with his unaided eyes from a nearby room.','The captain looked through the spyglass to see the distant sail more clearly.','spyglass是帮助观察远处物体的望远镜。','meaning'),[Q(1,'A spyglass is…','a small handheld telescope with one tube','a pair of swimming goggles','a short running race','That is the object’s source definition.','meaning'),Q(1,'What did the captain inspect through the spyglass?','A distant sail beyond the reef','A small spot on his sleeve','The inside of a spoon','The instrument helped him view a faraway object.','context'),Q(1,'Which phrase is natural?','look through a spyglass','look by a spyglass throughly','spyglass look to through','Through introduces the optical instrument used.','grammar'),Q(1,'Spyglass is a compound of spy and…','glass','grass','spring','The compound names a glass instrument for spying distant things.','word-formation')]);
P('squabble','Squabble is probably related to a Dutch or Low German word for quarrel; it means argue noisily about a small or unimportant matter.',[C('squabble.s1','家庭','The siblings squabbled over whose turn it was to wash the dishes.','兄妹俩为该谁洗碗这种小事吵了起来。','squabble over/about something; squabble with someone','不及物动词，指为琐事吵闹争执。','argument concerns a small chore.','家庭'),C('squabble.s2','家庭','A brief squabble about the television remote ended when their father changed the channel.','他们为电视遥控器短暂争吵了一下，父亲换了频道后争执便结束了。','a childish/family squabble; have a squabble','名词，指围绕小事发生的吵闹争执。','minor disagreement quickly ends.','家庭')],M('The siblings squabbled over a life-saving decision in a calm formal meeting, with no disagreement.','The siblings squabbled over the small chore in a noisy but petty argument.','没有分歧的正式讨论不是琐事上的吵闹。','meaning'),[Q(1,'Siblings who squabble over dishes…','argue noisily about a minor matter','quietly agree on every task','compete in a sprint','Squabble is a petty, noisy quarrel.','meaning'),Q(2,'A brief squabble about a remote is…','a small noisy argument','a legal hearing','a serious injury','The noun names a minor dispute.','context'),Q(1,'Which construction is natural?','squabble over whose turn it is','squabble whose turn overly','squabble at the turn to','Over introduces the disputed matter.','grammar'),Q(1,'Squabble is likely related to a Dutch/Low German word for…','quarrel','spoon','a spring season','The word history is associated with quarreling.','word-formation')]);
P('squad','Squad came through French escouade from Italian squadra, “square, group”; it means a small military or police unit or a team selected for a task or sport.',[C('squad.s1','军事','A squad of soldiers searched the warehouse after the alarm sounded.','警报响起后，一支士兵小队搜查了仓库。','a squad of soldiers/police; squad leader','名词，指军队或警察中的小型分队。','unit conducts a search.','军事'),C('squad.s2','体育','The coach named the final squad for the international tournament.','教练公布了参加国际锦标赛的最终队员名单。','a football/competition squad; squad selection','名词，也指为某项任务或比赛选出的小组成员。','players selected for tournament.','体育')],M('A squad of soldiers searched the warehouse, although a squad means a single civilian with no teammates.','A squad of soldiers searched the warehouse as a small organized unit.','squad指小队或团队，不是单个没有同伴的人。','meaning'),[Q(1,'A police squad is…','a small unit of officers','one officer working with no team','a particular place','Sense 1 is an organized unit.','meaning'),Q(2,'The final tournament squad is…','the players selected to compete','all spectators in the stadium','a type of vegetable','Sense 2 is a group chosen for sport.','context'),Q(1,'Which phrase is natural?','a squad of police officers','a squad police officers ofly','a police squadly of','Of introduces the members of the unit.','grammar'),Q(1,'Squad came through French escouade from Italian…','squadra','spora','sponte','The Italian word meant a square or group.','word-formation')]);
P('squalidity','Squalidity is formed from squalid + -ity; squalid comes from Latin squalidus, “filthy, rough,” and the noun means extreme dirtiness and wretchedness.',C('squalidity.s1','居住','The report documented the squalidity of the overcrowded basement, where waste was left for weeks.','报告记录了拥挤地下室的肮脏恶劣：废弃物在那里堆了好几周。','the squalidity of living conditions','名词，不可数，指环境或生活状况极度肮脏、悲惨。','waste and overcrowding show wretched conditions.','居住'),M('The squalidity of the basement was evident from its polished floors, fresh air, and spotless rooms.','The basement’s squalidity was evident from its filth and neglected living conditions.','干净整洁的环境不体现极度污秽和悲惨。','meaning'),[Q(1,'Squalidity means…','extreme dirtiness and wretchedness','a refined social manner','a small sports team','That is the abstract noun’s meaning.','meaning'),Q(1,'What showed the basement’s squalidity?','Waste and overcrowding','Polished floors and fresh air','A new springboard','The context describes filthy, poor conditions.','context'),Q(1,'Which phrase is natural?','the squalidity of the room','the squalid of the roomity','squalidity room into of','Of connects the condition with its setting.','grammar'),Q(1,'Squalidity is formed from squalid plus…','-ity','-less','-er','The suffix forms a noun for the quality or condition.','word-formation')]);
P('squall','Squall is of uncertain origin, perhaps related to Scandinavian storm words; it means a short, sudden, strong windstorm, sometimes with rain or snow.',C('squall.s1','天气','A sudden squall struck the lake, forcing the sailors to lower the sails.','一阵突如其来的狂风袭击湖面，迫使水手降下船帆。','a sudden squall; a squall of wind/rain','名词，指持续时间较短、突然出现的强风暴，有时伴雨雪。','brief storm requires action.','天气'),M('A squall struck the lake as a calm, windless afternoon with no sudden change in weather.','A squall struck the lake with a sudden burst of strong wind.','squall指突然的狂风天气，不是平静无风。','meaning'),[Q(1,'A squall is…','a short, sudden storm of strong wind','a long period of calm air','a small grain crop','That is the weather sense.','meaning'),Q(1,'Why did sailors lower the sails?','A sudden squall hit the lake.','The lake became a quiet library.','A spore landed on the boat.','The windstorm made sailing hazardous.','context'),Q(1,'Which phrase is natural?','a squall of wind','a squallful windly','a wind squall to of','Of can describe the storm’s wind.','grammar'),Q(1,'The deeper origin of squall is…','uncertain','certainly Latin for purity','certainly from spouse','The history is not firmly settled.','word-formation')]);
P('squalor','Squalor comes from Latin squalor, “dirtiness, roughness,” from squalere, “be dirty”; it means a state of being filthy, run-down, and wretched.',C('squalor.s1','居住','The inspectors found families living in squalor without clean water or working toilets.','检查人员发现有家庭生活在污秽恶劣的环境中，既没有干净水，也没有可用厕所。','live in squalor; urban squalor','名词，不可数，指肮脏破败且令人悲惨的生活状况。','lack of sanitation shows degrading conditions.','居住'),M('The report described squalor in a spotless home with reliable sanitation and freshly painted rooms.','The report described squalor in a filthy, run-down home without sanitation.','清洁、设施完善的住所不属于污秽破败的环境。','meaning'),[Q(1,'Living in squalor means living…','in filthy and wretched conditions','in luxury and perfect cleanliness','in a sports team','That is the word’s sense.','meaning'),Q(1,'What did inspectors find?','No clean water or working toilets','A spotless home and full sanitation','A sonata rehearsal','The conditions demonstrate squalor.','context'),Q(1,'Which phrase is standard?','live in squalor','live at squalorly','squalor living to inly','In is the usual preposition after live.','collocation'),Q(1,'Squalor comes from Latin squalor, meaning…','dirtiness or roughness','song or singing','a betrothed person','The Latin source already referred to dirtiness.','word-formation')]);
P('squander','Squander has an uncertain early history; it means use money, time, or other resources carelessly so that they bring no worthwhile result.',C('squander.s1','资源','The council squandered its emergency fund on decorations instead of repairing the flood barrier.','市议会把应急资金浪费在装饰上，没有修复防洪堤。','squander money/time/resources on; squander an opportunity','及物动词，指不负责任地挥霍金钱、时间或机会。','fund is spent without addressing need.','资源'),M('She squandered her savings wisely by investing every dollar in a reliable plan that met her goals.','She squandered her savings on careless purchases that brought no useful result.','明智投资并达到目标不属于挥霍浪费。','meaning'),[Q(1,'To squander a fund is to…','use it carelessly without a good result','save it responsibly for emergencies','lend it under clear conditions','Squander means waste resources.','meaning'),Q(1,'Why was the council criticized?','It spent emergency money on decorations instead of repairs.','It repaired the flood barrier first.','It kept every dollar unused.','The example shows poor use of funds.','context'),Q(1,'Which phrase is natural?','squander time on trivial tasks','squander time at trivial taskly','squander to time a task','On introduces the unworthy use.','grammar'),Q(1,'The early origin of squander is…','uncertain','certainly from Latin squalor','certainly from square','The exact derivation is not securely known.','word-formation')]);
P('squandering','Squandering is formed from squander + -ing and names the careless use or waste of money, time, or opportunity.',C('squandering.s1','资源','The squandering of clean water during the drought angered residents.','干旱期间对清洁用水的浪费激怒了居民。','the squandering of money/time/resources','名词，指对本可有效利用的资源或机会的挥霍浪费。','water is wasted in scarce period.','资源'),M('The squandering of water conserved every drop and supplied the entire town efficiently.','The squandering of water wasted scarce supplies and angered residents.','节约并有效供水与浪费资源相反。','meaning'),[Q(1,'Squandering is…','careless waste of useful resources','careful preservation of every resource','a short windstorm','The noun names the act of wasting.','meaning'),Q(1,'Why were residents angry?','Clean water was wasted during a drought.','The town saved all its water.','A squad won a tournament.','The context identifies the squandered resource.','context'),Q(1,'Which phrase is natural?','the squandering of public funds','the squander of public fundsing','public funds squanderingly the','Of introduces the resource being wasted.','grammar'),Q(1,'Squandering is based on the verb…','squander','square','squeak','The -ing form names the action of squandering.','word-formation')]);
P('square','Square came through Old French esquarre from Latin exquadrare, “make square”; it names a four-equal-sided shape or public open space, describes shape/fairness, and means make square, match, or multiply by itself.',[C('square.s1','几何','Draw a square with four equal sides and four right angles.','画一个四边相等、四个角都是直角的正方形。','a square with four sides; square root','名词，指四边相等且四角为直角的平面图形，也指公共广场或平方。','geometric definition.','几何'),C('square.s2','形状','The carpenter cut a square panel to fit the cabinet door.','木匠切了一块方形面板，装进柜门。','square table/box; square corners','形容词，表示方形的，也可表示公平、结清。','panel has square shape.','形状'),C('square.s3','数学','Square the number seven and you get forty-nine.','把数字七自乘，结果是四十九。','square a number; square the figures with','动词，指使成方形、使相符，或把数字自乘。','seven multiplied by itself.','数学')],M('A square has four unequal sides and no right angles.','A square has four equal sides and four right angles.','正方形的定义要求四边相等且四角为直角。','meaning'),[Q(1,'A geometric square has…','four equal sides and four right angles','three sides of different lengths','one curved edge','Sense 1 gives the definition.','meaning'),Q(2,'A square cabinet panel is…','shaped with equal sides and right angles','a round transparent sheet','a number multiplied by itself','Sense 2 is the adjective meaning square-shaped.','context'),Q(3,'To square seven is to…','multiply seven by itself','add seven to itself once','draw a public plaza','Sense 3 is the mathematical verb.','meaning'),Q(1,'Which phrase is natural?','square the number','square to the number','squarely the number as a noun','Square takes the number as its object.','grammar')]);
P('squarely','Squarely is formed from square + -ly; it means directly and fully, not to one side or in a vague way.',C('squarely.s1','表达','The report squarely blamed the delay on the contractor’s missed deadline.','报告明确地把延误归咎于承包商错过了期限。','squarely face/blame/answer; squarely in the middle','副词，表示正面、直接且明确地。','responsibility is stated directly.','表达'),M('The report squarely blamed the contractor while refusing to identify who was responsible.','The report squarely blamed the contractor and stated the responsibility directly.','明确归责与拒绝说明责任人相矛盾。','meaning'),[Q(1,'The report squarely blamed the contractor means it…','directly and clearly assigned blame','hinted vaguely at someone else','discussed a square plaza','Squarely means directly and fully.','meaning'),Q(1,'What did the report identify?','The contractor’s missed deadline as the cause','No cause at all','A springtime celebration','The example shows direct assignment of responsibility.','context'),Q(1,'Which phrase is natural?','squarely face the issue','squarely facingly issue','face squarely to the issue at','Squarely modifies face and signals directness.','grammar'),Q(1,'Squarely is derived from the adjective…','square','squad','squall','The adverb adds -ly to square.','word-formation')]);
P('squash','Squash as a verb came through Anglo-French from a word meaning crush; the vegetable name has a separate Native American history, and the racket sport has its own later naming history.',[C('squash.s1','动作','The dropped cardboard box was crushed when the truck rolled over it.','卡车碾过掉落的纸箱后，纸箱被压扁了。','squash/crush something flat; squash into','及物动词，指用力挤压、压扁某物。','pressure flattens the box.','动作'),C('squash.s2','运动','They booked a squash court for a doubles match after work.','他们预订了一间壁球场，下班后打双打。','play squash; squash court/racket','名词，指在封闭场地内将小橡胶球击向前墙的运动。','players use an enclosed court and ball.','运动'),C('squash.s3','饮食','We roasted a winter squash and served it with rice.','我们烤了一只冬南瓜，配米饭一起吃。','winter/summer squash; squash soup','名词，指长在地面、外壳较硬的一类南瓜蔬菜。','vegetable is cooked for a meal.','饮食')],M('He squashed the empty paper box by gently lifting it without applying any pressure.','He squashed the empty paper box by pressing it until it flattened.','挤压使物体变扁，需要施加压力。','meaning'),[Q(1,'To squash a box is to…','press it until it becomes flat','keep it untouched and rigid','play it on a court','Sense 1 is the crushing verb.','meaning'),Q(2,'A squash court is used for…','a racket game played against a front wall','growing a vegetable','holding a spore sample','Sense 2 names the sport.','context'),Q(3,'A winter squash is…','a hard-shelled vegetable in the pumpkin family','a small telescope','a noisy argument','Sense 3 is the vegetable.','meaning'),Q(1,'Which phrase is natural?','squash the empty carton flat','squash the carton into flatly','squash to the carton flat','Flat describes the result of the pressing.','grammar')]);
P('squat','Squat is of uncertain Germanic origin; it means crouch with weight on the feet, live in an empty building without permission, or a small plain dwelling.',[C('squat.s1','姿势','The hikers squatted beside the trail to examine the tiny flowers.','徒步者蹲在小路旁，查看那些小花。','squat down; squat on one’s heels','不及物动词，指屈膝蹲坐、重心落在脚上。','knees bend and weight rests on feet.','姿势'),C('squat.s2','居住','Several families squatted in the abandoned hotel until the city found them housing.','市政府为几户家庭找到住处前，他们暂住在废弃旅馆里。','squat in an empty building; squat on land','动词，指未经许可住进空置建筑或占用土地。','occupancy is unauthorized.','居住'),C('squat.s3','居住','The workers lived in a squat with one small room and a leaking roof.','工人们住在一间简陋小屋里，屋里只有一个小房间，屋顶还漏水。','a small/plain squat; live in a squat','名词，指简陋、状况不佳的小屋。','dwelling is basic and run-down.','居住')],M('They squatted in the empty hotel with the owner’s written permission and a paid lease.','They squatted in the empty hotel without permission or rent.','未经许可占住才符合此处的squat义项。','meaning'),[Q(1,'A hiker who squats beside the trail…','crouches with weight resting on the feet','lies with arms stretched across a sofa','runs at full speed','Sense 1 is the posture.','meaning'),Q(2,'Families squatting in an empty building are…','living there without owning it or paying rent','staying under a legal lease','repairing the building for its owner','Sense 2 describes unauthorized occupation.','context'),Q(3,'A small, plain squat may be…','a simple dwelling in poor condition','a public square','a sports team','Sense 3 is the noun for a modest shelter.','meaning'),Q(1,'Which sentence is natural?','He squatted down to tie his boot.','He squat down to ties bootly.','He was squat to tie his boot.','The past-tense verb is squatted.','grammar')]);
P('squawk','Squawk is an imitative word for the loud, rough cry of a parrot or gull; as a verb it can also mean complain loudly.',C('squawk.s1','鸟类','The parrot squawked whenever someone entered the kitchen.','每当有人走进厨房，鹦鹉就会发出刺耳的叫声。','a parrot/gull squawks; let out a squawk','动词，指像鹦鹉或海鸥那样发出响亮粗哑的叫声，也可指大声抱怨。','bird makes harsh cry.','鸟类'),M('The parrot squawked in a silent, smooth whisper that no one could hear.','The parrot squawked with a loud, rough cry.','squawk指响亮刺耳的叫声，不是无声耳语。','meaning'),[Q(1,'A parrot that squawks…','makes a loud, rough cry','sings a quiet sonnet','releases a mist of water','Squawk describes a harsh animal call.','meaning'),Q(1,'When did the parrot squawk in the example?','When someone entered the kitchen','Only when the room was empty','After it was put in a springboard','The bird’s call follows the person’s arrival.','context'),Q(1,'Which phrase is natural?','the gull squawked loudly','the gull squawkedly loud','the gull made a squawkly loudly','Squawk is the verb for the bird’s cry.','grammar'),Q(1,'Squawk is imitative of…','a loud, rough animal cry','a silent pause','a gentle spring','Its sound imitates the call it names.','word-formation')]);
P('squeak','Squeak is imitative of a short, high-pitched sound; as a noun it names that sound, and as a verb it means make it or narrowly succeed.',[C('squeak.s1','声音','The unoiled hinge gave a squeak when the door opened.','门打开时，没有上油的铰链发出一声短促尖响。','a short/high squeak; hear a squeak','名词，指像未上油铰链发出的短促、高音声音。','hinge makes brief high noise.','声音'),C('squeak.s2','声音','The rusty gate squeaked each time the wind pushed it.','每当风推动生锈的门，门就吱呀作响。','a door/hinge squeaks; squeak open','动词，指发出短促而尖的声音，也可指勉强成功。','movement creates squeal.','声音'),C('squeak.s2','结果','The team squeaked through to the final by one point.','这支队以一分之差惊险晋级决赛。','squeak through/by; squeak into the final','动词，口语指以极小优势或险些失败的状态成功。','one-point margin.','结果')],M('The gate squeaked without making any sound when the wind pushed it.','The gate squeaked with a short, high-pitched sound as it moved.','squeak作动词表示发出尖短声音，与完全无声相反。','meaning'),[Q(1,'A hinge’s squeak is…','a short, high-pitched noise','a prolonged low thunderstorm','a piece of sportswear','Sense 1 names the sound.','meaning'),Q(2,'The rusty gate squeaked means it…','made a short high sound as it moved','opened silently','was covered in spotless paint','Sense 2 is the verb use.','context'),Q(2,'A team that squeaked through…','advanced by a very small margin','won by hundreds of points','was eliminated early','The informal verb can mean succeed narrowly.','meaning'),Q(1,'Squeak is a sound-imitating word for…','a brief, high-pitched noise','a low smooth hum','a storm cloud','Its pronunciation echoes the noise.','word-formation')]);
P('squeal','Squeal is imitative of a long, high-pitched cry; it means cry out in that way from pain, fear, or excitement.',C('squeal.s1','声音','The children squealed with excitement when the lights came on at the fair.','游乐场的灯亮起时，孩子们兴奋地尖叫起来。','squeal with delight/pain; let out a squeal','动词，指因疼痛、害怕或兴奋而发出长而尖的叫声。','excited children cry out.','声音'),M('The children squealed with excitement in a deep, low whisper that made no high sound.','The children squealed with excitement in loud, high-pitched cries.','squeal是高而长的尖叫，不是低声耳语。','meaning'),[Q(1,'Children squealed with excitement means they…','cried out in long, high-pitched voices','whispered quietly','made a brief mechanical click','That is the meaning of squeal.','meaning'),Q(1,'Why did they squeal at the fair?','They were excited when the lights came on.','They were studying sputum.','They were arranging receipts.','The example gives excitement as the cause.','context'),Q(1,'Which phrase is natural?','squeal with delight','squeal of delightly with','squealingly a delight','With introduces the emotion prompting the cry.','grammar'),Q(1,'Squeal is imitative of…','a long, high-pitched cry','a silent gesture','a slow footstep','Its sound echoes the cry it describes.','word-formation')]);
P('squeeze','Squeeze comes from Old English cwēsan, “press, crush”; it means press firmly, force one’s way through a narrow space, or the act/difficult situation caused by pressure.',[C('squeeze.s1','动作','Squeeze the orange over a bowl to catch all the juice.','把橙子挤在碗上方，好接住所有果汁。','squeeze something; squeeze juice from','及物动词，指用力压挤，常用于从水果中榨汁。','pressure releases juice.','动作'),C('squeeze.s2','空间','We squeezed through the narrow gap between the fence and the wall.','我们从围栏和墙之间的狭窄缝隙挤了过去。','squeeze through/past; squeeze into a space','动词，指勉强挤进、挤过狭小空间。','bodies force passage through gap.','空间'),C('squeeze.s3','状况','The rent increase put many families in a financial squeeze.','租金上涨使许多家庭陷入经济拮据。','a tight/financial squeeze; a squeeze on budgets','名词，指因钱、空间或时间不足而承受的压力。','higher costs reduce available money.','状况')],M('They squeezed through the narrow opening without moving into or through the gap at all.','They squeezed through the narrow opening by pressing their bodies through it.','squeeze through表示用力穿过狭窄空间。','meaning'),[Q(1,'Squeeze an orange means…','press it to extract juice','freeze it until it becomes solid','place it on a stage','Sense 1 is firm pressing.','meaning'),Q(2,'Squeezed through a narrow gap means…','forced a way through a small space','stood still outside the gap','built a wider road','Sense 2 concerns restricted passage.','context'),Q(3,'A financial squeeze is…','a difficult situation with too little money','a comfortable surplus','a small bird call','Sense 3 is figurative pressure from limited resources.','meaning'),Q(1,'Which preposition fits?','squeeze through the gap','squeeze at the gap throughly','squeeze to through gap','Through introduces the narrow passage.','grammar')]);
P('squeezer','Squeezer is formed from squeeze + -er; it names a tool used to press juice out of fruit.',C('squeezer.s1','厨房','She used a handheld squeezer to extract lemon juice without dropping seeds into the bowl.','她用手持榨汁器挤柠檬汁，避免柠檬籽掉进碗里。','a lemon/citrus squeezer; use a squeezer','名词，指通过挤压水果来榨汁的工具。','tool presses fruit for juice.','厨房'),M('She used a squeezer to extract lemon juice by leaving the fruit untouched and collecting no liquid.','She used a squeezer to press the lemon and collect its juice.','榨汁器通过挤压水果取汁。','meaning'),[Q(1,'A squeezer is…','a tool that presses fruit to extract juice','a small telescope for distant objects','a utensil for stirring tea only','That is the source sense.','meaning'),Q(1,'Why did she use a handheld squeezer?','To get lemon juice without seeds in the bowl','To store a coil of wire','To light a theater stage','The tool presses fruit and lets juice flow out.','context'),Q(1,'Which phrase is natural?','a lemon squeezer','a lemon squeezerful','a squeezer lemoning','The noun names the tool used on the lemon.','grammar'),Q(1,'Squeezer is formed from squeeze plus…','-er','-ity','-less','The suffix identifies a device or agent that squeezes.','word-formation')]);
P('squid','Squid is an English sea-animal name of uncertain deeper origin; it is a marine cephalopod with a torpedo-shaped body, eight arms, and two longer tentacles.',C('squid.s1','海洋生物','A squid shot backward through the water by forcing a jet from its mantle.','一只鱿鱼从外套膜喷出水流，向后迅速游动。','a giant/small squid; squid ink','名词，指身体呈梭形、有八腕和两条较长触腕的海生头足动物。','animal moves by jet propulsion.','海洋生物'),M('The squid had a shell and six legs and lived permanently on dry land.','The squid was a marine cephalopod with eight arms and two longer tentacles.','鱿鱼是海生头足动物，有腕和触腕，不是六足陆生动物。','distinction'),[Q(1,'A squid is…','a marine cephalopod with eight arms and two longer tentacles','a six-legged land insect','a type of seaweed','That is the source description.','meaning'),Q(1,'How did the squid move backward?','It forced a jet of water from its body.','It ran on six legs.','It used a springboard.','The example describes jet propulsion.','context'),Q(1,'Which phrase is natural?','a squid in the harbor','a squidly in harbor','squid of the harboring','In introduces the animal’s location.','grammar'),Q(1,'The deeper origin of squid is…','uncertain','certainly Latin for “firm”','certainly the Greek for “small bird”','The English animal name has no firmly established deeper derivation.','word-formation')]);
P('squint','Squint is of uncertain origin; it means partly close the eyes to cope with bright light or see more clearly, and a squint is a condition in which the eyes point in different directions.',[C('squint.s1','视觉','She squinted into the low sun to read the street sign.','她眯起眼睛迎着低垂的阳光，辨认路牌。','squint at/into; squint to see','不及物动词，指因强光或看清细节而几乎闭上眼睛。','sunlight prompts narrowed eyes.','视觉'),C('squint.s2','医学','The optometrist checked whether the child’s squint affected depth perception.','验光师检查孩子的斜视是否影响了深度知觉。','have/develop a squint; treat a squint','名词，指双眼不能同时朝同一方向看的状况。','eyes point in different directions.','医学')],M('She squinted into the bright sun by opening her eyes as wide as possible to block no light.','She squinted into the bright sun by partly closing her eyes.','强光下眯眼是部分闭眼，不是把眼睛睁到最大。','meaning'),[Q(1,'She squinted into the sun means she…','partly closed her eyes to see','stared with eyes fully open to increase glare','looked through a spyglass','Sense 1 describes narrowing the eyes.','meaning'),Q(2,'A child’s squint is…','a condition in which the eyes do not point in the same direction','a tiny dark mark on the skin','an ordinary sport','Sense 2 is the eye condition.','context'),Q(1,'Which phrase is natural?','squint at the small print','squint the small print at','squintingly at the print to','At introduces what is being viewed.','grammar'),Q(1,'The deeper origin of squint is…','uncertain','certainly Latin for square','certainly from sport','No firm earlier derivation is asserted.','word-formation')]);
P('squirrel','Squirrel came through Anglo-French esquirel from Latin sciurus, ultimately Greek skiouros, “shadow-tail,” referring to its bushy tail.',C('squirrel.s1','动物','A squirrel buried an acorn beneath the oak and raced up the trunk.','一只松鼠把橡子埋在橡树下，然后迅速爬上树干。','red/gray squirrel; a squirrel climbs a tree','名词，指常爬树、储藏坚果且有蓬松大尾巴的小型啮齿动物。','animal stores a nut and climbs.','动物'),M('The squirrel buried an acorn, although it was a marine animal with tentacles and no tail.','The squirrel buried an acorn; it was a small tree-climbing rodent with a bushy tail.','松鼠是啮齿动物，不是有触腕的海洋动物。','distinction'),[Q(1,'A squirrel is…','a small rodent that climbs trees and often stores nuts','a marine cephalopod','a horse-drawn vehicle','That is the dictionary sense.','meaning'),Q(1,'What did the squirrel bury?','An acorn beneath an oak','A spool of film in a theater','A spoonful of salt','The example shows nut-storing behavior.','context'),Q(1,'Which phrase is natural?','a squirrel climbed the tree','a squirrel climbed treeful','squirrelly climbed the tree at','The animal is the subject of the verb.','grammar'),Q(1,'The Greek source skiouros referred to the animal’s…','shadow-like tail','ability to sprint','taste for sour fruit','The compound is traditionally interpreted as “shadow-tail.”','word-formation')]);
P('squirt','Squirt is of uncertain deeper origin, probably imitative; it means force liquid through a small opening in a thin fast stream, the stream itself, or informally a small rude person.',[C('squirt.s1','液体','The child squirted water through the narrow nozzle at the pavement.','孩子从细喷嘴里把水喷向人行道。','squirt liquid out; squirt something into','及物动词，指让液体从小口快速呈细流喷出。','water forced through nozzle.','液体'),C('squirt.s2','液体','A squirt of lemon juice brightened the soup.','挤出的一点柠檬汁让汤的味道清爽起来。','a squirt of cream/juice; a quick squirt','名词，指受压喷出的一股细液流。','small jet added to soup.','液体'),C('squirt.s3','称呼','The older players called him a little squirt, but he soon proved himself on the team.','年长队员叫他小不点，但他很快就在队里证明了自己。','a little/young squirt','非正式名词，带有轻蔑意味，指身材小、无礼或讨厌的人，常指小孩。','dismissive nickname for boy.','称呼')],M('She squirted water through the nozzle by keeping the bottle sealed and releasing no liquid.','She squirted a thin stream of water through the nozzle.','squirt表示液体受压喷出，不能是完全不释放液体。','meaning'),[Q(1,'To squirt water through a nozzle is to…','force it out in a thin fast stream','keep it sealed inside the bottle','pour it slowly from a wide bowl','Sense 1 is the verb use.','meaning'),Q(2,'A squirt of lemon juice is…','a small stream of liquid squeezed out','a whole lemon tree','a large bowl of soup','Sense 2 names the stream or small amount.','context'),Q(3,'Calling someone a little squirt is…','an informal, often dismissive way to call them small or annoying','a formal medical diagnosis','a compliment on their height','Sense 3 is the informal person sense.','meaning'),Q(1,'Which phrase is natural?','a squirt of water from the bottle','a squirtful water at from','squirt of water bottle to the','Of introduces the liquid stream.','grammar')]);
P('stab','Stab comes from Old English stæbban, “pierce, thrust”; as a verb it means push a pointed object into something, and as a noun it can mean a wound, sudden pain, or an attempt.',[C('stab.s1','安全','The guard stabbed the padded target with a blunt training spear.','警卫用钝头训练矛刺向带垫子的靶子。','stab someone/something with; stab at','及物动词，指用尖锐物向某人或某物猛刺。','pointed weapon thrusts into target.','安全'),C('stab.s2','受伤','The report described a stab wound to the victim’s shoulder.','报告描述了受害者肩部的一处刺伤。','a stab wound; die of a stab','名词，指刺伤，也可指突然剧痛或尝试。','wound is caused by a thrust.','受伤'),C('stab.s2','感受','A sudden stab of pain made him stop climbing the stairs.','一阵突如其来的刺痛让他停下了爬楼梯。','a stab of pain/guilt; a stab at something','名词，也指突然的一阵疼痛、情绪或一次尝试。','sharp pain arrives suddenly.','感受')],M('The guard stabbed the padded target with the blunt spear but never pushed the point into it.','The guard stabbed the target by thrusting the spear point into its padding.','stab表示尖端向内刺入，不能只是没有刺入的接触。','meaning'),[Q(1,'To stab a target is to…','thrust a pointed object into it','cover it with a soft blanket','squeeze it from both sides','Sense 1 describes a thrusting action.','meaning'),Q(2,'A stab wound is…','an injury made by a pointed weapon','a harmless spot of ink','a respiratory sample','Sense 2 names the injury.','context'),Q(2,'A stab of pain is…','a sudden sharp pain','a long mild itch','a public sports event','Sense 2 also covers a sudden painful sensation.','meaning'),Q(1,'Which construction is natural?','stab at the target','stab to the target at','stab the target withly','At can mark the thing one thrusts toward.','grammar')]);
P('stabilise','Stabilise is the British spelling of stabilize, formed from stable + -ise; it means make something steady or become steady after changing.',[C('stabilise.s1','工程','Workers added a brace to stabilise the damaged wall before repairs began.','维修开始前，工人加装支撑以稳固受损的墙体。','stabilise a structure/price; stabilise something','及物动词，指使某物稳定、牢固，不再移动或变化。','brace prevents movement.','工程'),C('stabilise.s2','经济','After several weeks of sharp declines, food prices began to stabilise.','食品价格大幅下跌数周后开始趋于平稳。','prices stabilise; stabilise after a change','不及物动词，指经过一段变化后变得稳定。','decline stops fluctuating.','经济')],M('Workers stabilised the wall by removing its supports and making it less secure.','Workers stabilised the wall by adding a brace to hold it steady.','移除支撑会使墙更不稳，不是使其稳定。','meaning'),[Q(1,'Workers stabilise a wall by…','making it firm and steady','removing every support','painting it a bright color','Sense 1 is the causative verb.','meaning'),Q(2,'Prices began to stabilise means they…','stopped rising or falling sharply','continued to fluctuate wildly','became a sports team','Sense 2 is the intransitive use.','context'),Q(1,'Which spelling is British English?','stabilise','stabilize','stabilizingly','Stabilise is the British spelling variant.','spelling'),Q(1,'Stabilise is formed from stable plus…','-ise','-less','-ment','The suffix forms a verb meaning make or become stable.','word-formation')]);
P('stabiliser','Stabiliser is the British spelling of stabilizer, formed from stabilise + -er; it is a device, fin, or chemical that reduces unwanted movement or change.',C('stabiliser.s1','工程','The camera’s stabiliser reduced the shake in footage recorded from the moving boat.','摄像机稳定器减少了从行驶船只上拍摄画面的晃动。','a camera/chemical stabiliser; install a stabiliser','名词，指减少振动、晃动或化学变化的装置或物质。','device reduces unwanted motion.','工程'),M('The camera stabiliser increased every vibration so that the footage shook more than before.','The camera stabiliser reduced vibration and kept the footage steadier.','稳定器的作用是减少不必要的晃动。','meaning'),[Q(1,'A camera stabiliser is used to…','reduce unwanted movement in footage','make a camera shake more','measure a short race','That is the device sense.','meaning'),Q(1,'What did the stabiliser do on the moving boat?','It reduced camera shake.','It made the boat sink.','It sprayed the lens with water.','The context shows movement reduction.','context'),Q(1,'Which spelling is British?','stabiliser','stabilizer','stabilizor','Stabiliser uses the British -iser ending.','spelling'),Q(1,'Stabiliser is formed from stabilise plus…','-er','-ity','-ful','The suffix names a device or agent.','word-formation')]);
P('stability','Stability comes from Latin stabilitas, from stabilis “firm, steady”; it is the quality of being firm and unlikely to fail or change.',C('stability.s1','结构','The wide base gives the ladder enough stability to stand on uneven ground.','宽大的底座让梯子足够稳，即使放在不平的地面上也能立住。','structural/economic stability; ensure stability','名词，不可数，指牢固稳定、不易倒下、失败或变化的性质。','wide base prevents tipping.','结构'),M('The ladder’s stability was proven when it tipped over on every flat surface.','The ladder’s stability was shown by its wide base and secure footing.','频繁倾倒说明梯子不稳定。','meaning'),[Q(1,'A ladder’s stability concerns whether it…','stands firmly without tipping','has bright paint','makes a squeaking noise','That is the physical quality.','meaning'),Q(1,'Why did the wide base help?','It kept the ladder steady on uneven ground.','It made the ladder lighter than air.','It created a springtime garden.','A broad base improves stability.','context'),Q(1,'Which phrase is natural?','political stability','political stablely','stability political of the','Stability is a noun modified by political.','grammar'),Q(1,'Stability comes from Latin stabilitas, based on stabilis meaning…','firm or steady','alone or lonely','spotted or marked','The Latin adjective carried the sense of firmness.','word-formation')]);
P('stabilization','Stabilization is the American spelling of stabilisation and means the act or process of stopping movement, change, or decline so a system holds steady.',C('stabilization.s1','经济','The stabilization of the currency followed months of coordinated action by the central bank.','央行采取数月协调行动后，货币趋于稳定。','price/currency stabilization; stabilization of','名词，指使系统不再剧烈波动或继续下滑的过程。','policy reduces fluctuations.','经济'),M('The stabilization of prices meant that they continued to rise and fall more sharply each day.','The stabilization of prices meant that their fluctuations became smaller.','稳定化减少波动，不会使波动越来越剧烈。','meaning'),[Q(1,'Stabilization of a currency is…','the process of making its value steadier','a sudden increase in daily fluctuations','a type of sport','That is the noun’s sense.','meaning'),Q(1,'What followed coordinated central-bank action?','The currency became more stable.','Prices began changing more wildly.','A stadium was built.','The example describes reduced currency volatility.','context'),Q(1,'Which spelling is standard in American English?','stabilization','stabilisation only','stabilizasion','The US form uses -ization.','spelling'),Q(1,'Stabilization names the process related to the verb…','stabilize','squabble','squeeze','The noun refers to making or becoming stable.','word-formation')]);
P('stabilize','Stabilize is formed from stable + -ize; it means hold something steady so it stops moving or fluctuating, or become steady again.',[C('stabilize.s1','医疗','The medication helped stabilize the patient’s blood pressure overnight.','这种药物帮助患者的血压在夜间稳定下来。','stabilize a patient/price; stabilize something','及物动词，指使某物或某人状态稳定、不再波动。','treatment reduces fluctuations.','医疗'),C('stabilize.s2','变化','The market began to stabilize after the emergency announcement.','紧急公告发布后，市场开始趋于稳定。','markets stabilize; stabilize after a fall','不及物动词，指停止大幅波动并恢复平稳。','movement becomes steady.','变化')],M('The medication stabilized the patient’s blood pressure by causing it to fluctuate more violently.','The medication helped stabilize the patient’s blood pressure by reducing its fluctuations.','稳定血压会减少剧烈波动，而不是使其加剧。','meaning'),[Q(1,'Medication can stabilize blood pressure by…','helping it remain steady','making it fluctuate more violently','turning it into springwater','Sense 1 means cause something to become steady.','meaning'),Q(2,'A market that begins to stabilize…','stops changing sharply and becomes steadier','starts fluctuating more wildly','has turned into a stadium','Sense 2 is the intransitive meaning.','context'),Q(1,'Which spelling is American English?','stabilize','stabilise','stabilyse','American English uses -ize.','spelling'),Q(1,'The suffix -ize in stabilize means…','make or become','a person who does','without','The verb is built from stable with -ize.','word-formation')]);
P('stabilizer','Stabilizer is the American spelling of stabiliser; it is a device or substance that reduces roll, vibration, or chemical change.',C('stabilizer.s1','工程','The boat’s stabilizer reduced its roll when waves struck from the side.','侧面浪打来时，船上的稳定装置减轻了横摇。','a boat/camera stabilizer; chemical stabilizer','名词，指降低摇晃、振动或化学变化的装置或物质。','device counters roll.','工程'),M('The boat’s stabilizer made the vessel roll more sharply whenever waves struck.','The boat’s stabilizer reduced the vessel’s roll in rough water.','稳定装置会减少横摇，而不是将其放大。','meaning'),[Q(1,'A boat stabilizer helps…','reduce the vessel’s roll','increase its side-to-side motion','measure its speed in a race','That is a common device function.','meaning'),Q(1,'What happened when waves struck the boat?','The stabilizer reduced its rolling.','The stabilizer made it roll more.','The stabilizer turned it into a stagecoach.','The context illustrates motion control.','context'),Q(1,'Which spelling is standard in American English?','stabilizer','stabiliser only','stabilizor','The US spelling uses -izer.','spelling'),Q(1,'A chemical stabilizer can reduce…','unwanted chemical change','a person’s spouse','the number of stadium seats','The source definition includes chemicals that prevent change.','meaning')]);
P('stable','Stable comes from Latin stabilis, “firm, steady”; a separate noun stable is from Latin stabulum, “standing place,” and means a building for horses.',[C('stable.s1','状态','The patient’s condition remained stable throughout the night.','患者整夜的病情都保持稳定。','remain/become stable; a stable condition','形容词，指不易移动、改变或恶化。','condition does not fluctuate.','状态'),C('stable.s2','动物','The horses returned to the stable after the morning ride.','早晨骑行后，马匹回到了马厩。','a horse stable; stable door','名词，指饲养马匹的建筑。','horses are housed there.','动物')],M('The patient was stable all night, with rapidly worsening vital signs and sudden repeated changes.','The patient remained stable all night, with no major changes in vital signs.','不断恶化与稳定状态相反。','meaning'),[Q(1,'A stable condition is…','unlikely to change or fail suddenly','changing rapidly every minute','a building for horses','Sense 1 means steady.','meaning'),Q(2,'A horse stable is…','a building where horses are kept','a reliable blood pressure','a short-distance race','Sense 2 is the noun for the shelter.','context'),Q(1,'Which spelling distinguishes the noun?','The horse returned to the stable.','The horse returned to be stable.','The horse stablely returned.','Stable is a noun naming the horse building.','grammar'),Q(1,'The adjective stable comes from Latin stabilis, meaning…','firm or steady','horse or rider','sound or voice','That Latin source gives the adjective sense.','word-formation')]);
P('stack','Stack comes from Old Norse stakkr, “haystack”; as a noun it is a neat pile, and as a verb it means arrange things in a pile.',[C('stack.s1','物品','A stack of clean plates stood beside the sink.','水槽旁放着一摞干净盘子。','a stack of books/plates; a tall stack','名词，指整齐叠放在一起的一堆东西。','objects form a pile.','物品'),C('stack.s2','整理','Stack the boxes against the wall, leaving the doorway clear.','把箱子堆在墙边，并让门口保持畅通。','stack boxes/books; stack something on top of','及物动词，指把物品整齐地堆起来。','boxes arranged in a pile.','整理')],M('The worker stacked the boxes neatly by scattering each one across a different room.','The worker stacked the boxes neatly on top of one another.','stack表示堆叠，不是分散摆放。','meaning'),[Q(1,'A stack of plates is…','a neat pile of plates','one plate by itself','a group of horses','Sense 1 is the pile.','meaning'),Q(2,'To stack boxes against a wall is to…','arrange them in a pile there','scatter them in different rooms','squeeze through a gap','Sense 2 is the verb.','context'),Q(1,'Which phrase is natural?','a stack of books','a stacks of book','a stack books ofly','Of introduces the objects in the pile.','grammar'),Q(1,'Stack came from Old Norse stakkr, meaning…','haystack','song','spore','The borrowed source word referred to a pile such as a haystack.','word-formation')]);
P('stadium','Stadium comes from Latin stadium, from Greek stadion, a unit and place for races; today it is a large building or area with seating for spectators at sports events.',C('stadium.s1','体育','The stadium filled with fans before the championship match.','冠军赛开始前，体育场里挤满了球迷。','a football/athletics stadium; fill a stadium','名词，指有成排座位、供观众观看体育比赛的大型场馆或场地。','fans occupy seats for a match.','体育'),M('The stadium was a tiny private bedroom with no space for spectators or games.','The stadium was a large sports venue with rows of seats for spectators.','stadium是大型比赛场馆，不是私人卧室。','meaning'),[Q(1,'A stadium is…','a large venue with seats for watching sport','a small spoon used for food','a horse shelter','That is the modern source sense.','meaning'),Q(1,'Why did the stadium fill before the match?','Fans came to watch the championship.','The horses needed a stable.','Workers were stacking boxes there only.','The context explains the spectators’ presence.','context'),Q(1,'Which phrase is natural?','a crowded stadium','a stadiumly crowded','crowd stadium into a','Crowded modifies the noun stadium.','grammar'),Q(1,'Stadium ultimately comes from Greek…','stadion','stabilitas','sponte','The Latin term came from Greek stadion.','word-formation')]);
P('staff','Staff comes through Old French estaffe, ultimately of Germanic origin; as a noun it means all employees of an organization, and as a verb it means provide an organization with workers.',[C('staff.s1','职场','The hospital staff met at dawn to review the overnight admissions.','医院全体工作人员在黎明时开会，查看夜间入院情况。','medical/teaching staff; a member of staff','集合名词，指某机构雇用的全体工作人员。','employees hold a meeting.','职场'),C('staff.s2','职场','The company will staff the new branch with experienced technicians.','公司将为新分部配备有经验的技术人员。','staff a department/office; fully staffed','及物动词，指为机构或岗位配备工作人员。','workers assigned to branch.','职场')],M('The clinic was staffed by opening its doors but employing no workers at all.','The clinic was staffed with nurses and receptionists before opening.','staff作动词表示配备员工；没有雇员就不算配备人员。','meaning'),[Q(1,'Hospital staff means…','the people employed by the hospital','the patients waiting for treatment','a stadium’s seats','Sense 1 is the collective noun.','meaning'),Q(2,'The company will staff a branch means it will…','provide workers for it','close it permanently','build a springboard','Sense 2 is the verb meaning supply personnel.','context'),Q(1,'Which phrase is natural?','a member of staff','a staff of member','staffs member ofly','Member of staff is a common expression.','grammar'),Q(1,'The word staff entered English through Old French…','estaffe','squalor','stadion','Its history passes through Old French and has a Germanic source.','word-formation')]);
P('stag','Stag comes from Old English stagga; it is a fully grown male deer, especially a red deer.',C('stag.s1','动物','A stag stood at the edge of the forest, its antlers visible above the grass.','一只牡鹿站在森林边缘，鹿角高高露出草丛。','a red stag; a stag’s antlers','名词，指成年雄鹿，尤其是赤鹿。','male deer has antlers.','动物'),M('The stag at the forest edge was a female fawn with no antlers.','The stag at the forest edge was a fully grown male deer with antlers.','stag特指成年雄鹿，不是雌性幼鹿。','distinction'),[Q(1,'A stag is…','a fully grown male deer','a female young deer','a type of bird','That is the dictionary sense.','meaning'),Q(1,'What was visible above the grass?','The stag’s antlers','A stadium roof','A sprayer nozzle','The context gives a typical feature of a male deer.','context'),Q(1,'Which phrase is natural?','a red stag in the forest','a red stagly in forest','a stag of redly forest','In introduces the animal’s location.','grammar'),Q(1,'Stag comes from Old English…','stagga','sponte','sciurus','The modern noun descends from Old English stagga.','word-formation')]);
P('stage','Stage came through Old French estage, “floor, story, period,” related to Latin stare, “stand”; it names a performance platform or a phase in a process, and as a verb means organize or present an event.',[C('stage.s1','表演','The actors walked onto the stage as the orchestra finished its overture.','管弦乐队演完序曲后，演员们走上舞台。','on/off the stage; stage a play','名词，指演员或音乐家表演的高台或区域。','actors perform on raised area.','表演'),C('stage.s2','进程','The project is at an early stage, so the team has not chosen a final design.','项目仍处于早期阶段，因此团队还没有确定最终设计。','at/in the first/final stage; stage of development','名词，指过程中的某个特定时期或步骤。','work is not yet complete.','进程'),C('stage.s3','活动','The charity staged a public concert to raise money for the shelter.','慈善机构举办了一场公开音乐会，为避难所筹款。','stage an event/performance; stage a protest','及物动词，指组织并举行公开活动或演出。','organization arranges concert.','活动')],M('The charity staged a concert by refusing to organize, advertise, or hold any performance.','The charity staged a concert by organizing and presenting the event.','stage作动词表示组织并举行活动。','meaning'),[Q(1,'Actors walk onto a stage to…','perform before an audience','store horses','measure water pressure','Sense 1 names the performance area.','meaning'),Q(2,'An early stage of a project is…','a particular point near the beginning of its process','the final completed product','a sports stadium','Sense 2 means phase.','context'),Q(3,'A charity staged a concert means it…','organized and presented the event','watched it without arranging it','made it a small film image','Sense 3 is the verb.','meaning'),Q(1,'Which phrase is natural?','at an early stage','on an early stage ofly','early stage at in the','At is used in the phrase at a stage.','grammar')]);
P('stagecoach','Stagecoach combines stage + coach: stage referred to a scheduled section of a journey, and coach came through French from Hungarian kocsi, a horse-drawn vehicle; it was a closed carriage running scheduled routes before railways.',C('stagecoach.s1','交通','The stagecoach stopped at the inn to change horses before continuing west.','公共马车在客栈停下换马，然后继续向西行驶。','travel by stagecoach; stagecoach route','名词，指铁路出现前沿固定线路定期行驶的封闭式马车。','scheduled carriage changes horses.','交通'),M('The stagecoach ran on an electric railway and never used horses or scheduled stops.','The stagecoach followed a scheduled route and changed horses at the inn.','stagecoach是铁路时代前的马拉公共马车。','meaning'),[Q(1,'A stagecoach was…','a closed horse-drawn vehicle on scheduled routes','an electric passenger train','a small sea animal','That is the historical vehicle sense.','meaning'),Q(1,'Why did it stop at the inn?','To change horses before continuing','To load a stadium audience','To spray the road with water','The context depicts long-distance horse transport.','context'),Q(1,'Which phrase is natural?','travel by stagecoach','travel by a stagecoachly','stagecoach travel to bying','By is common when naming a means of travel.','grammar'),Q(1,'Coach entered the word through French from Hungarian…','kocsi','squalidus','spondeo','The vehicle word has a Hungarian source.','word-formation')]);
P('stagecraft','Stagecraft combines stage + craft and names the practical art of presenting a play effectively, including acting, design, lighting, and movement.',C('stagecraft.s1','戏剧','The production’s careful stagecraft made a small room look like a vast ship’s cabin.','这部作品精妙的舞台艺术手法把一间小屋变成了宽阔的船舱。','lighting/set stagecraft; learn the craft of stagecraft','名词，不可数，指有效呈现戏剧所需的舞台表演与技术艺术。','design and lighting transform the space.','戏剧'),M('The production’s stagecraft made the room look convincing by using no acting, lighting, design, or movement.','The production’s stagecraft used acting, lighting, and design to transform the room.','舞台艺术手法依靠表演与技术设计来营造效果。','meaning'),[Q(1,'Stagecraft is…','the art of presenting a play effectively','the building where horses are kept','a short storm at sea','That is the theatrical sense.','meaning'),Q(1,'How did stagecraft change the small room?','Design made it look like a ship’s cabin.','It moved the entire audience into a stadium.','It turned into a squid.','The example shows the effect of theatrical design.','context'),Q(1,'Which phrase is natural?','the stagecraft of the production','the stagecraft production ofly','stagecraft to production at','Of relates the craft to the production.','grammar'),Q(1,'Stagecraft combines stage and…','craft','spore','spouse','Craft names the skill or art used on stage.','word-formation')]);
})();
